update public.species set scientific_name = $v$Hoplisoma panda$v$, genus = $v$Hoplisoma$v$, former_names = array[$v$Corydoras panda$v$]::text[], summary = $v$The adorable panda-marked dwarf cory. It prefers slightly cooler, very clean water.$v$, body = $v$Panda corys have white bodies with black eye-patches and a tail spot. The 2024 revision moved it from Corydoras to Hoplisoma, though stores still sell it as Corydoras panda; it likes cooler, pristine water.$v$ where slug = $v$panda-cory$v$;
