update public.species set plant_safe = false, summary = $v$The round-bodied, ornate goldfish varieties (oranda, ranchu, fantail and more), all one species.$v$, body = $v$Every fancy goldfish, including the oranda, ranchu, fantail, ryukin, black moor and bubble eye, is a selectively bred variety of Carassius auratus, not a separate species. Their round bodies make them slower swimmers prone to swim-bladder issues, so feed sinking food and keep flow gentle.$v$ where slug = $v$fancy-goldfish$v$;
