update public.species set social = $v$Pairs$v$, body = $v$Golden wonders are hardy, non-annual killifish that patrol the top of the tank hunting. Keep a lid on, since they jump, and avoid bite-sized tankmates.$v$ where slug = $v$golden-wonder-killifish$v$;
update public.species set swim_level = $v$Middle$v$, summary = $v$One of the smallest fish in the world: a tiny, peaceful native livebearer.$v$ where slug = $v$least-killifish$v$;
