update public.species set summary = $v$A tiny jewel-like gourami that can audibly 'croak', great for nano tanks.$v$ where slug = $v$sparkling-gourami$v$;
update public.species set body = $v$The 'two spots' plus the eye make the third, hence the name. Males can be territorial, so give space and avoid keeping multiple males in smaller tanks.$v$ where slug = $v$three-spot-gourami$v$;
