update public.species set body = $v$Hardy, active and prolific, and the males are living fireworks. Thrives in hard, alkaline water and breeds readily, so expect fry. Keep more females than males in a planted nano or community tank.$v$ where slug = $v$endlers-livebearer$v$;
update public.species set summary = $v$The endlessly colorful, endlessly breeding beginner classic. Keep more females than males.$v$ where slug = $v$guppy$v$;
