-- Duplicates
do $d$
declare dup uuid; main uuid; t text;
begin
  select id into dup from public.species where slug = $v$x-ray-tetra$v$;
  select id into main from public.species where slug = $v$pristella-tetra$v$;
  if dup is null or main is null then return; end if;
  foreach t in array array['species_photos', 'species_videos'] loop
    if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = t and column_name = 'species_id') then
      execute format('update public.%I set species_id = $1 where species_id = $2', t) using main, dup;
    end if;
  end loop;
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'breeding_guides' and column_name = 'species_slug') then
    update public.breeding_guides set species_slug = $v$pristella-tetra$v$ where species_slug = $v$x-ray-tetra$v$;
  end if;
  delete from public.species where id = dup;
end $d$;

do $d$
