    update public.breeding_guides set species_slug = $v$multifasciatus-shell-dweller$v$ where species_slug = $v$multifasciatus$v$;
  end if;
  delete from public.species where id = dup;
end $d$;

-- Glossary
update public.glossary_terms set sections = $g$[{"text": "- Floating plastic boxes: clip inside the tank, often with a slotted floor so livebearer fry drop away from the mother.\n- Net breeders: a fine mesh bag on a frame. Water flows through freely, which keeps it cleaner than solid plastic.\n- Hang-on-back boxes: sit outside the tank and get a steady flow of tank water from an air pump or small pump. These hold more water and are often the best box choice for raising fry.", "heading": "Types of breeder boxes"}, {"text": "Set the box up in an area with gentle flow, near the heater but not against it. For livebearers, move the female only when she is very close to giving birth, with a boxy, squared-off belly and a dark gravid spot. Return her to the main tank right after she drops her fry.\n\nFeed fry small amounts several times a day and siphon leftover food from the bottom of the box daily, since the small volume fouls quickly. Move fry out once they are too large to fit in adult mouths, usually after 4 to 6 weeks.", "heading": "How to use one"}, {"text": "- Moving a pregnant female in too early. Days of confinement can stress her enough to cause a premature birth or a lost brood.\n- Using a solid box with no water flow, which lets ammonia build up.\n- Overcrowding fry as they grow.\n- Leaving the box where tankmates nip through the mesh.\n\nIf you plan to breed regularly, a separate 5 to 10 gallon fry tank with a sponge filter is easier on the fish than any box.", "heading": "Common mistakes"}]$g$::jsonb, faq = $g$[{"a": "They can, especially for pregnant females kept in them for days. Use them for short stays and give fry a roomier setup as they grow.", "q": "Do breeder boxes stress fish?"}, {"a": "Usually 4 to 6 weeks, until they are too big to be eaten by the adults in the main tank.", "q": "How long should fry stay in a breeder box?"}, {"a": "Yes, but wait until she is very close to giving birth, then return her to the main tank soon after the fry arrive.", "q": "Can I put a pregnant guppy in a breeder box?"}]$g$::jsonb where slug = $g$breeder-box$g$;
update public.glossary_terms set sections = $g$[{"text": "Bettas, paradise fish and many gouramis build bubble nests, along with a few catfish such as the hoplo catfish. Labyrinth fish evolved in still, warm, oxygen-poor water, and the nest keeps eggs up in the moist, oxygen-rich layer at the surface. Males usually build under a floating leaf or in a calm corner.", "heading": "Which fish build them"}, {"text": "A nest generally means the male is healthy, comfortable and mature. It does not mean he is lonely or needs a mate. Some healthy males rarely build nests, so a missing nest on its own is not a warning sign. Watch appetite, color and activity instead.", "heading": "What a nest means"}, {"text": "Breeders often lower the water to 5 or 6 inches, keep it around 80 to 82 F, turn off or baffle the filter and add floating plants. After spawning, the male catches falling eggs and spits them into the nest. Remove the female right away, since he will chase her off aggressively.\n\nEggs hatch in about 24 to 48 hours. Remove the male once the fry swim freely, usually 2 to 3 days after hatching, or he may start eating them.", "heading": "Using a nest to breed"}, {"text": "It is fine to disturb a nest during routine maintenance when no eggs are in it. The male will simply build a new one, often within a day. If eggs or fry are in the nest, skip large water changes and keep the surface still until the fry are free swimming.", "heading": "Nests and water changes"}]$g$::jsonb where slug = $g$bubble-nest$g$;
update public.glossary_terms set body = $g$Many fish spawn poorly, or not at all, on a basic flake diet alone. A few weeks of conditioning builds body condition, improves egg quality and fertility, and often triggers spawning on its own when paired with the right water changes or temperature cues.$g$ where slug = $g$conditioning$g$;
update public.glossary_terms set sections = $g$[{"text": "- Physical deformities such as bent spines, missing gill covers or misshapen fins\n- Fish that are much slower growing or weaker than their siblings\n- Colors or fin types that don't match the strain\n- Too many fish for the space available, which stunts the rest\n- Excess males in livebearer groups", "heading": "Why breeders cull"}, {"text": "For many hobbyists, culling simply means removing fish from the breeding program. Healthy fish with minor color or fin faults can be kept as pets, given to other hobbyists or sold as pet quality, so long as they are labeled honestly and not used to breed the strain. Fish with serious deformities or illness that will suffer should be euthanized humanely.", "heading": "Culling does not always mean killing"}, {"text": "A widely recommended method among hobbyists and many vets is an overdose of clove oil mixed into a small container of tank water, which sedates the fish before it dies. Avoid flushing, freezing a live fish or leaving it out of water, all of which are inhumane. Feeding culls to larger fish is common but debated, and it can spread disease if the culls are sick.", "heading": "Doing it humanely"}, {"text": "Many breeders do a first pass when fry are a few weeks old and deformities become visible, then cull again as color and finnage develop. Cull early and steadily rather than waiting until a tank is overcrowded. Keep notes on what you remove and why, so you can spot which parents keep throwing faults and drop them from the breeding program.", "heading": "When to cull"}]$g$::jsonb where slug = $g$culling$g$;
update public.glossary_terms set sections = $g$[{"text": "- Egg scatterers: tetras, danios, barbs and rasboras spray eggs over plants or gravel and leave them, often eating them right away.\n- Substrate spawners: many cichlids and corydoras stick eggs on rocks, glass or leaves, and some guard them.\n- Cave spawners: plecos and many dwarf cichlids lay inside caves, usually guarded by a parent.\n- Bubble nesters: bettas and gouramis place eggs in a floating nest.\n- Mouthbrooders: carry eggs in the mouth.\n- Egg buriers: annual killifish lay eggs in mud, and the eggs survive the dry season until rain returns.", "heading": "Types of egg layers"}, {"text": "For scatterers, give eggs somewhere to fall out of reach: a layer of marbles, a mesh grid above the bottom, a spawning mop or a thick clump of moss. Remove the adults after spawning. For species that guard their eggs, it is often best to leave the parents alone in their own tank, since some pairs learn to raise fry well.", "heading": "Protecting the eggs"}, {"text": "Most aquarium eggs hatch in about 1 to 5 days depending on species and temperature, though some, such as pleco eggs, can take a week or more. Unfertilized eggs turn white and fuzzy with fungus within a day or two, and fungus can spread to good eggs. Remove white eggs with a pipette, keep gentle water flow over the clutch, and consider hatching eggs in a separate container if fungus is a regular problem.", "heading": "Hatching and fungus"}, {"text": "Newly hatched fry live off their yolk sac for anywhere from about a day to a week, depending on species. Once they swim freely, most need very tiny first foods such as infusoria or microworms before moving on to baby brine shrimp.", "heading": "Feeding the fry"}]$g$::jsonb, faq = $g$[{"a": "Many do, especially egg scatterers. Removing adults after spawning or giving eggs a protected place to fall is the usual solution.", "q": "Do egg laying fish eat their eggs?"}, {"a": "Fertilized eggs stay clear or slightly amber and you may see a developing eye spot. Unfertilized eggs turn white and fuzzy within a day or two.", "q": "How do I know if fish eggs are fertilized?"}, {"a": "Usually about 1 to 5 days for common aquarium species, faster in warmer water. Pleco eggs can take a week or more, and some killifish eggs take weeks or months.", "q": "How long do fish eggs take to hatch?"}]$g$::jsonb where slug = $g$egg-layer$g$;
update public.glossary_terms set definition = $g$Fry are newly hatched or newborn baby fish, from hatching or birth until they grow into juveniles a few weeks or months later.$g$ where slug = $g$fry$g$;
update public.glossary_terms set faq = $g$[{"a": "It is a planned form of inbreeding. The difference is careful selection and record keeping, with outcrosses added when health starts to slip.", "q": "Is line breeding the same as inbreeding?"}, {"a": "It varies with how the trait is inherited. A simple recessive trait can breed true in as few as 2 or 3 generations, while traits controlled by several genes can take many more.", "q": "How many generations does it take to fix a trait?"}, {"a": "Yes, for a few generations, and breeders often do. Repeated sibling pairings without selection or outcrossing raises the risk of deformities.", "q": "Can you breed brother and sister fish?"}]$g$::jsonb where slug = $g$line-breeding$g$;
update public.glossary_terms set sections = $g$[{"text": "Males have a modified anal fin called a gonopodium that delivers sperm. Females can store sperm for several months, so one mating can produce several broods, even with no male present. Gestation usually takes about 3 to 5 weeks depending on species and temperature, with mollies often taking longer, and a brood can range from a few fry to 100 or more from a large female.", "heading": "How livebearers reproduce"}, {"text": "- A growing belly that becomes boxy or squared off just before birth\n- A dark gravid spot near the vent that gets larger and darker\n- Hiding, staying near the heater or bottom, or refusing food\n- Restless swimming in one corner shortly before dropping fry", "heading": "Signs of pregnancy and birth"}, {"text": "Keep 1 male for every 2 or 3 females so no single female is harassed constantly. If you don't want fry, keep a single sex or keep a few hungry tankmates that will eat most of them. Dense plants like moss and floating plants help some fry survive if you do want to raise them. Mollies and platies also appreciate harder, more alkaline water, around 7.5 or higher.", "heading": "Keeping things under control"}, {"text": "Livebearer fry are born large enough to eat crushed flakes and baby brine shrimp right away. Feed small amounts several times a day, keep the water clean with small, frequent changes, and expect most fry to reach a safe size in about 4 to 6 weeks.", "heading": "Fry care"}]$g$::jsonb, faq = $g$[{"a": "Guppies, endlers, platies and swordtails usually take about 3 to 4 weeks. Mollies often take longer, and cooler water stretches it out for all of them.", "q": "How long are livebearers pregnant?"}, {"a": "She can give birth without a male present by using stored sperm from an earlier mating, sometimes for several broods.", "q": "Can a female guppy get pregnant without a male?"}, {"a": "Yes, adults often eat fry. Dense plants, a breeder box or a separate tank improve survival.", "q": "Do livebearers eat their babies?"}]$g$::jsonb where slug = $g$livebearer$g$;
update public.glossary_terms set sections = $g$[{"text": "- Maternal: the female carries the brood. Most Lake Malawi cichlids, including mbuna and haps, work this way.\n- Paternal: the male carries it, as in several wild betta species and arowanas.\n- Biparental: both parents share the job, seen in some tilapia and related cichlids.", "heading": "Types of mouthbrooders"}, {"text": "Look for a swollen, pouch-like throat, a square-looking jaw, chewing motions as she turns the eggs, refusing food and hiding. A holding Malawi female typically carries for about 21 to 28 days, depending on temperature. She eats little or nothing in that time and will lose condition, so she needs good feeding before and after.", "heading": "Signs a fish is holding"}, {"text": "In a busy cichlid tank, a holding female may be chased and spit early. Many keepers move her to a quiet tank or a large breeder net, moving her gently to avoid scaring her into spitting. Once she releases the fry, give her a week or two to recover before returning her to the group.\n\nSome breeders strip fry by gently opening the mouth into a container around day 14 to 21 and raising the young in an egg tumbler or a separate fry tank. It boosts fry numbers and lets the female recover sooner, but it is debated because it stresses the mother. Letting her hold to term is the gentler choice.", "heading": "Helping a holding fish"}, {"text": "Mouthbrooder fry are large when released and can eat crushed flakes, powdered pellets and baby brine shrimp right away.", "heading": "Feeding the fry"}]$g$::jsonb where slug = $g$mouthbrooder$g$;
update public.glossary_terms set sections = $g$[{"text": "- Brighter or darker breeding colors\n- A male chasing a female, displaying or nudging her\n- A pair cleaning a flat rock, leaf, cave or glass\n- Females looking round and full when viewed from above\n- A small breeding tube appearing near the vent in many cichlids\n- More aggression toward tankmates as a pair claims territory", "heading": "Signs fish are about to spawn"}, {"text": "Most fish spawn when diet, water and season line up. Conditioning with live or frozen foods is the starting point. Then a cue often sets it off: a large, slightly cooler water change for corydoras, a small temperature rise for many tropical species, or soft, acidic water for many tetras. Morning light is a frequent trigger for egg scatterers.", "heading": "Common spawning triggers"}, {"text": "Decide right away whether you want to raise the young. Egg scatterers and most community fish will eat eggs within hours, so remove the eggs or the adults. Guarding species like many cichlids may raise the brood themselves if they have the tank to themselves. Remove white, unfertilized eggs to limit fungus, and prepare first foods before the fry are free swimming.", "heading": "What to do after a spawn"}, {"text": "A single spawn can range from a few eggs a day in many killifish and a few dozen in some dwarf cichlids to hundreds in many tetras and thousands in some larger fish. Expect many to be lost in the first weeks. Not every spawn succeeds, and young pairs often eat their first few clutches before getting it right.", "heading": "Spawn size"}]$g$::jsonb where slug = $g$spawn$g$;
update public.glossary_terms set sections = $g$[{"text": "An air pump does not add much oxygen directly through its bubbles. The rising bubbles move water from the bottom to the surface and break up the surface, which is where oxygen enters and carbon dioxide leaves. That matters most in warm water, crowded tanks, during medication and anytime fish are gasping at the surface.", "heading": "What it does"}, {"text": "Pumps are rated by tank size, but depth matters more than volume. A deeper tank needs more pressure to push air to the bottom. Size up if you run several outlets or an air stone at the bottom of a tank deeper than about 18 inches. A pump with an adjustable output, or a gang valve on the line, lets you dial in the flow and split it between several devices.", "heading": "Choosing the right size"}, {"text": "- Fit a check valve on every line, especially if the pump sits below the waterline.\n- Set it on a soft pad or hang it to cut down on vibration noise.\n- Give the power cord a drip loop so water can't run along it into the outlet.\n- Keep a battery-powered pump on hand for outages.", "heading": "Setup tips"}, {"text": "Running heavy aeration in a CO2-injected planted tank drives off the CO2 you are paying for. A pump that has grown weak or noisy usually needs a new diaphragm, which is cheap and easy to replace. Clogged air stones also make a pump work harder, so replace them when bubbles shrink.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$air-pump$g$;
update public.glossary_terms set sections = $g$[{"text": "Cut the airline tubing and push each end onto the valve. Most valves have an arrow or a colored side. The arrow points in the direction air travels, from the pump toward the tank. Color coding varies between makers, so follow the arrow if there is one. Blow gently through it to check: air should pass one way only.", "heading": "How to install it"}, {"text": "Install the valve outside the tank, close to the aquarium and above the floor, so any water stopped by the valve stays in the short section of tubing near the tank. Use one valve on each airline. If you split air with a gang valve, put a check valve on each line leading into the water.", "heading": "Where to put it"}, {"text": "- The air pump sits on the floor or in a cabinet below the waterline\n- You run airline to a sponge filter, air stone or CO2 diffuser\n- CO2 setups use a CO2-rated check valve to protect the regulator\n\nIf the pump sits above the water level, a check valve is optional but still cheap insurance.", "heading": "When you need one"}, {"text": "Check valves can stick or slowly fail as minerals and grime build up. If airflow suddenly drops or bubbles sputter, the valve is a likely culprit. Replace them every year or so, and swap any that let water through when tested. A failing valve can also let water creep into the line slowly, so check the tubing for water now and then.", "heading": "Common problems"}]$g$::jsonb, faq = $g$[{"a": "The arrow points away from the pump, toward the tank, in the direction the air flows.", "q": "Which way does a check valve go on an air pump?"}, {"a": "It is not strictly required, since water won't siphon back into a pump that sits above the water level, but it is still worth adding for safety.", "q": "Do I need a check valve if my pump is above the tank?"}, {"a": "It is likely installed backward or stuck. Flip it to test, and replace it if air still won't pass.", "q": "Why is no air coming through my check valve?"}]$g$::jsonb where slug = $g$check-valve$g$;
update public.glossary_terms set body = $g$Too little CO2 means weak plant growth and algae, while too much can suffocate fish. A drop checker gives a simple, constant visual check, so you can tune CO2 injection safely without guessing or relying only on pH readings. It is strongly recommended for any injected CO2 setup.$g$, sections = $g$[{"text": "The checker holds a few milliliters of indicator fluid separated from the tank water by a small pocket of air. CO2 passes through that air gap into the fluid and changes its pH, which changes its color. Because only gas crosses over, things like fertilizers and driftwood tannins don't throw off the reading.", "heading": "How it works"}, {"text": "- Blue: too little CO2, roughly under 15 ppm\n- Green: the usual target, around 30 ppm\n- Yellow: too much CO2, roughly 40 to 50 ppm or more, a danger to fish\n\nUse the 4 dKH reference solution, not tank water, for an accurate reading. Tank water in the checker makes the color meaningless.", "heading": "Reading the colors"}, {"text": "Place the drop checker low in the tank, away from the CO2 diffuser and out of any direct bubble stream, ideally on the side opposite the diffuser. Replace the fluid every 2 to 4 weeks, since it slowly drifts. Look at it against a white background to judge the color more easily.", "heading": "Setup tips"}, {"text": "A drop checker takes about 1 to 2 hours to react to changes, so it shows the average level over the past while, not what is happening right now. Adjust your bubble rate in small steps and wait several hours before judging. For faster readings, some keepers also track the pH drop: a fall of about 1 full point from degassed water roughly equals 30 ppm.", "heading": "Lag time and limits"}]$g$::jsonb where slug = $g$drop-checker$g$;
update public.glossary_terms set body = $g$Uneaten food, fish waste and plant debris settle into gravel and slowly break down into ammonia, which the tank then turns into nitrite and nitrate. Vacuuming removes that waste before it pollutes the tank, and it combines two chores into one, so it is the most useful maintenance tool most fishkeepers own.$g$, sections = $g$[{"text": "- Unplug the heater before you start, and the filter too if the water level will drop below it.\n- Start the siphon with the built-in squeeze bulb or by shaking the tube, with a bucket set below the tank.\n- Push the wide tube straight down into the gravel, let debris swirl up, then lift it before gravel gets sucked out.\n- Work in a pattern across the bottom until you've removed 25 to 50 percent of the water.\n- Refill with dechlorinated water close to the tank's temperature.", "heading": "How to use one"}, {"text": "Over sand, hover the tube just above the surface so it lifts debris without pulling sand. Pinch the hose to slow the flow if needed. In planted tanks, vacuum the open areas and leave root zones mostly alone, since some debris there feeds plants. Aquasoil should be vacuumed very lightly, if at all.", "heading": "Sand and planted tanks"}, {"text": "- Vacuuming the whole tank deeply every week in a brand new setup; doing half the bottom per change is gentler.\n- Sucking up fry, shrimp or snails. Cover the intake with fine mesh or a sponge.\n- Forgetting to restart the heater and filter afterward.\n- Refilling with untreated tap water.", "heading": "Common mistakes"}, {"text": "For tanks over about 40 gallons, a long hose that connects to a sink faucet saves carrying buckets. Add dechlorinator for the full tank volume when refilling directly from the tap.", "heading": "Larger tanks"}]$g$::jsonb where slug = $g$gravel-vacuum$g$;
update public.glossary_terms set sections = $g$[{"text": "Intensity is measured as PAR at the substrate. Rough guidelines:\n\n- Low light: under about 30 PAR. Java fern, anubias, crypts and mosses do well.\n- Medium light: 30 to 50 PAR. Most stem plants and swords.\n- High light: over 50 PAR. Carpeting plants and red stems, usually with CO2 injection.\n\nMany manufacturers list PAR at certain depths, which is more useful than wattage.", "heading": "Light for plants"}, {"text": "Plants absorb red and blue light most strongly, though they use other colors too, and a full spectrum light around 6,500 K looks natural to our eyes and grows plants well. Lights with extra red make plants and fish colors pop. Very blue lights look dramatic but can wash out colors in freshwater tanks.", "heading": "Spectrum and color"}, {"text": "More light means plants need more fertilizer and carbon to keep up. If they can't, algae takes advantage. Start with a moderate setting and 6 to 8 hours a day, then increase slowly as plants grow. Keep tanks out of direct sunlight, which is impossible to control and a classic algae trigger.", "heading": "Balancing light and algae"}, {"text": "LED lights are now standard: efficient, cool running and long lasting. Pick one that covers the full length of the tank, and consider a dimmable model so you can tune intensity. For deep tanks over about 20 inches, plan on a stronger light to reach the bottom. Raising the light a few inches or lowering its brightness is an easy fix if plants melt or algae appears soon after an upgrade.", "heading": "Choosing a fixture"}]$g$::jsonb where slug = $g$lighting$g$;
update public.glossary_terms set sections = $g$[{"text": "A pump injects air into a tall chamber, creating a dense cloud of tiny bubbles. Proteins, fats and other dissolved organics cling to the bubble surfaces and ride them to the top, where they build up as a thick, brown foam. That foam spills into a collection cup, which you empty and rinse every few days.\n\nBecause waste leaves the system before bacteria turn it into ammonia and then nitrate, a skimmer lowers the nutrient load that feeds algae and keeps reef water clear.", "heading": "How a skimmer works"}, {"text": "In salt water, dissolved salts keep tiny bubbles from merging, which allows a stable foam to form. In fresh water, bubbles pop almost instantly and very little waste sticks to them, so a skimmer produces little or no skimmate. A few keepers try them on heavily stocked freshwater systems, but results are poor and inconsistent.\n\nFreshwater keepers get the same benefit in other ways:\n\n- Regular water changes of 25 to 50 percent a week\n- Mechanical filtration you rinse often so trapped food does not rot\n- Fast-growing plants that soak up nitrate\n- Activated carbon or resin media for dissolved organics and tannins", "heading": "Why it does not work in freshwater"}, {"text": "Skimmers are rated by tank size, but those ratings assume light stocking. Many reefers pick a model rated for about 1.5 to 2 times their actual volume. Most sit in a sump, though hang-on models exist for small tanks. Expect a break-in period of one to two weeks before foam forms steadily, and adjust the water level so the foam is wet but not overflowing.", "heading": "Choosing one for a marine tank"}]$g$::jsonb where slug = $g$protein-skimmer$g$;
update public.glossary_terms set sections = $g$[{"text": "- Gravel: easy to vacuum and lets water flow through it. Choose smooth, rounded pieces if you keep bottom feeders.\n- Sand: natural look, great for corydoras, loaches and other fish that sift. Debris sits on top, so it is easy to siphon from the surface.\n- Aquasoil: baked clay granules packed with nutrients for planted tanks. It softens water and lowers pH, and usually breaks down over one to three years.\n- Crushed coral or aragonite: raises pH and hardness, useful for African cichlids and livebearers in soft-water areas.\n- Bare bottom: easiest to keep spotless, common in fry, quarantine and grow-out tanks.", "heading": "The main types"}, {"text": "Plan on 1 to 2 inches for fish-only gravel or sand and 2 to 3 inches for planted tanks, sloping deeper toward the back. A rough rule is about 1 pound of gravel per gallon for each inch of depth, so 1.5 to 2 pounds per gallon for a 1.5 to 2 inch layer, but check the bag; aquasoil is lighter and sold by volume.", "heading": "How much to use"}, {"text": "Rinse gravel and sand in a bucket until the water runs mostly clear. Do not rinse aquasoil; it falls apart. Many aquasoils release ammonia for the first few weeks, so cycle the tank fully and do frequent water changes before adding livestock. In inert gravel or sand, add root tabs near heavy root feeders like swords and crypts.", "heading": "Setup tips"}, {"text": "- Using sharp, jagged gravel with catfish and loaches\n- Laying sand very deep without plants or snails to stir it\n- Never vacuuming, which lets waste build up\n- Adding pH-raising rock or coral substrate to a soft-water tank by accident", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$substrate$g$;
update public.glossary_terms set sections = $g$[{"text": "- Glass stick-in: floats or sticks to the glass inside the tank. Cheap and fairly accurate, but can break.\n- Stick-on strip: a liquid crystal strip on the outside of the glass. Easy to read, but it is affected by room temperature and can be off by a few degrees.\n- Digital with probe: a probe sits in the water and the display mounts outside. Usually the most accurate and easiest to read.\n- Controllers and smart monitors: digital units that can cut power to a heater or send alerts if the temperature drifts.", "heading": "Types of thermometers"}, {"text": "Place it on the opposite side of the tank from the heater, about midway down, so you read the overall water temperature rather than the warm spot next to the heater. In tanks over about 75 gallons, two thermometers at each end show whether heat is spreading evenly.", "heading": "Where to put it"}, {"text": "Compare it with a second thermometer, or test it in a glass of ice water, which should read 32°F. If two thermometers disagree by more than a degree or two, trust the digital probe and replace the odd one out.", "heading": "Checking accuracy"}, {"text": "Most tropical community fish do well at 74 to 80°F. Goldfish and many coldwater species prefer the mid 60s to low 70s. Discus and some wild-type fish like 82 to 86°F. What matters most is stability; swings of more than 2 to 3°F in a day stress fish.", "heading": "What the numbers mean"}]$g$::jsonb where slug = $g$thermometer$g$;
update public.glossary_terms set sections = $g$[{"text": "Barbels are packed with taste receptors and touch-sensitive nerves. Fish sweep them across the bottom to locate worms, crumbs and sinking food, often in murky water or at night when eyesight is less useful. Species range from the short paired barbels of corydoras and many barbs to the long sweeping barbels of pictus catfish and the several pairs of small barbels around the mouth of kuhli loaches.", "heading": "What barbels do"}, {"text": "Barbels that look short, red, ragged or are missing entirely are a sign of trouble. The cause is debated in the hobby. Many keepers blame sharp or jagged gravel, while others point to bacterial infection from dirty substrate full of rotting food and waste. In practice the two often go together, and fixing both works best:\n\n- Switch to smooth sand or rounded fine gravel for bottom feeders\n- Vacuum the substrate regularly, especially under decor\n- Keep ammonia and nitrite at 0 ppm and nitrate low with steady water changes\n- Avoid overfeeding so food does not rot in the substrate", "heading": "Barbel erosion"}, {"text": "Usually yes. Once conditions improve, barbels regrow over several weeks to a few months. Severe infections that reach the jaw need a broad-spectrum antibacterial treatment in a hospital tank. Barbels that never regrow after months of good care may have been damaged too far.", "heading": "Will they grow back?"}, {"text": "Use a soft net and avoid pinning bottom feeders against rough decor. Many catfish also have sharp fin spines that tangle in nets, so a cup or container is gentler for moving them.", "heading": "Handling tips"}]$g$::jsonb where slug = $g$barbels$g$;
update public.glossary_terms set sections = $g$[{"text": "In the wild, fish read safety from the behavior of other fish. A school swimming calmly in the open means no predator is nearby. In a tank, nervous fish like apistogrammas and other dwarf cichlids, or many wild-caught species, take the same cue and venture out more. With territorial cichlids, dithers also give them something else to posture at, so a single tankmate or mate is not chased nonstop.", "heading": "How dithering works"}, {"text": "- Peaceful and quick, so they can avoid trouble\n- Mostly use the middle and upper water, away from the main fish's territory on the bottom\n- Not small enough to be eaten by the fish they are dithering\n- Kept in a proper group, usually six or more\n\nCommon picks include rasboras, danios, hatchetfish, pencilfish and many tetras for dwarf cichlids. Giant danios, rainbowfish or larger barbs suit bigger cichlids.", "heading": "Choosing dither fish"}, {"text": "Choosing dithers that also breed on the bottom or claim caves just adds competition. Adding fin nippers like tiger barbs to a tank of angelfish or bettas causes new problems. Very small fish like neon tetras can become food for angelfish and larger cichlids. Dithers will not fix a tank that is too small or has no hiding places, so provide both.", "heading": "Common mistakes"}, {"text": "No. Many community tanks have dithering built in because they already hold active schooling fish. It matters most in species tanks with shy or aggressive centerpiece fish.", "heading": "Is it always needed?"}]$g$::jsonb where slug = $g$dither-fish$g$;
update public.glossary_terms set sections = $g$[{"text": "Dorsal fins range from tiny and spiked to tall and sail-like. Some fish have two dorsal fins, like rainbowfish and gobies, and many cichlids have a spiny front section and a soft back section. Tetras and many catfish also have a small fleshy adipose fin behind the dorsal, which is a separate fin. Sailfin mollies and bettas have been bred for especially large dorsals.", "heading": "Shapes and variations"}, {"text": "A dorsal held flat against the body for more than a short time is a stress signal. Common causes:\n\n- Ammonia, nitrite or high nitrate\n- Temperature too low or swinging\n- Bullying from tankmates\n- Early disease such as ich, velvet or internal parasites\n- New arrival still settling in\n\nTest your water first, check the heater, and watch for spots, scratching or rapid breathing. Fixing water usually brings fins back up within a day or two.", "heading": "Clamped dorsal fin"}, {"text": "The dorsal fin is a favorite target for fin nippers, especially on slow fish with tall fins like angelfish, bettas and sailfin mollies. Torn edges from nipping are clean bites, while fin rot looks ragged with discolored margins. Fins regrow in clean water once the cause is removed.", "heading": "Damage and nipping"}, {"text": "In many species males have a longer, more pointed or more colorful dorsal. Examples include many gouramis, some tetras, rainbowfish and sailfin mollies, where males usually carry the bigger sail. Always compare several adults, since young fish show few differences.", "heading": "Sexing by the dorsal fin"}]$g$::jsonb where slug = $g$dorsal-fin$g$;
update public.glossary_terms set sections = $g$[{"text": "The gravid spot is darkened skin over the area where the female carries her young. Mature females usually show a faint spot even when not pregnant. As fry develop, the spot gets larger and darker, and the belly swells. In light-colored guppies you can sometimes see the tiny eyes of the fry through the skin near the end. On black mollies and dark platies the spot can be hard to see, so watch belly shape instead.", "heading": "What it is"}, {"text": "- The belly develops a boxy or squared-off look just behind the gills\n- The spot is very dark and large\n- She hides, hangs near the heater or in plants, or stays near the surface\n- Loss of appetite and trembling or straining\n\nLivebearer pregnancy usually lasts about 3 to 5 weeks for guppies and platies and often longer for mollies, depending on species and temperature.", "heading": "Signs she is close to giving birth"}, {"text": "Adults eat newborn fry, including the mother. Thick plants like java moss, floating plants or hornwort give fry places to hide. Breeder boxes work but can stress the female, so move her only when she is very close and return her soon after birth. Many keepers prefer a separate, heavily planted tank.", "heading": "Protecting the fry"}, {"text": "Female livebearers store sperm and can have several batches of fry from one mating. A female bought from a mixed store tank may give birth weeks later even with no males in your tank.", "heading": "Good to know"}]$g$::jsonb, faq = $g$[{"a": "Look for a darker, larger gravid spot near the anal fin and a swollen belly. Near the end, the belly looks boxy behind the gills.", "q": "How do I know if my guppy is pregnant?"}, {"a": "Guppies usually take about 3 to 5 weeks. Mollies often take longer, commonly several weeks more, and cooler water slows things down for both.", "q": "How long are guppies and mollies pregnant?"}, {"a": "No. Males have a gonopodium, a narrow rod-like anal fin, instead. The gravid spot is a female trait.", "q": "Do males have a gravid spot?"}]$g$::jsonb where slug = $g$gravid-spot$g$;
update public.glossary_terms set sections = $g$[{"text": "- Most plecos and many other suckermouth catfish\n- Kuhli loaches and many other loaches\n- Pictus catfish and upside-down catfish\n- Black ghost knifefish and other knifefish\n- Many shrimp, snails and crayfish become more active after dark\n\nSome species, like corydoras, are crepuscular, most active at dawn and dusk.", "heading": "Common nocturnal fish"}, {"text": "Day-active tankmates eat most food before nocturnal fish come out. Drop sinking pellets, wafers or frozen food in shortly after lights go out, or 15 to 30 minutes before. Target caves and hiding spots, and check that bellies look rounded rather than sunken. Remove uneaten food the next morning if it is still there.", "heading": "Feeding them"}, {"text": "Give each nocturnal fish a cave, driftwood hollow or tube to rest in during the day. A tank with plenty of cover, dim areas under floating plants and fewer hyperactive tankmates helps them venture out sooner. Many become more visible over time as they settle in.", "heading": "Helping them feel secure"}, {"text": "A dim blue or red light lets you watch without fully disrupting their night, since many fish see red light poorly. Keep it low and avoid running bright lights around the clock. Most tanks do well with 8 to 10 hours of light and a real dark period, which both day and night species need. Avoid tapping the glass or switching bright room lights on suddenly at night, since startled nocturnal fish can crash into decor.", "heading": "Watching them at night"}]$g$::jsonb, faq = $g$[{"a": "Yes. Fish need a regular dark period for rest and normal behavior. Most tanks do well with lights on about 8 to 10 hours a day, so they get a long, regular dark period.", "q": "Do fish need darkness at night?"}, {"a": "Most plecos are nocturnal and hide in caves or under wood during the day. Look for them after lights out.", "q": "Why do I never see my pleco?"}, {"a": "A very dim light for an hour or two is fine for viewing, but leaving it on all night can disturb sleep patterns. Most keepers put it on a timer.", "q": "Is a moonlight on all night OK for fish?"}]$g$::jsonb where slug = $g$nocturnal$g$;
update public.glossary_terms set sections = $g$[{"text": "- Nitrite poisoning: chloride competes with nitrite at the gills and protects fish while you fix the cycle\n- Ich and some external parasites, especially for salt-tolerant fish like goldfish and livebearers\n- Minor wounds and stress after shipping or injury\n- Short dips for some external parasites, done at higher strength for only a few minutes and only by experienced keepers", "heading": "When salt helps"}, {"text": "Doses vary by goal, and fish vary in tolerance. A mild tonic is often around 1 tablespoon per 5 gallons. Treatment levels for parasites are commonly about 1 to 3 teaspoons per gallon, added gradually over a day or two, with the upper end used only for salt-tolerant fish like goldfish and livebearers. Always dissolve salt in tank water first, and dose by the gallons of water you actually have, not the tank's label size.", "heading": "How much to use"}, {"text": "Scaleless and sensitive fish such as corydoras, plecos and other catfish, loaches, tetras from soft water and many wild-caught fish can be stressed or harmed even at low doses. Most live plants suffer at treatment levels. Shrimp and snails are sensitive too. In a mixed tank, treat sick fish in a separate hospital tank.", "heading": "Who does not tolerate it"}, {"text": "Salt does not evaporate. When you top off with fresh water the salt stays behind. Only water changes remove it, so after treatment do several partial water changes over a week or two, replacing with unsalted water. When doing water changes during treatment, add back only the salt for the volume you removed.", "heading": "How to remove it"}]$g$::jsonb where slug = $g$aquarium-salt$g$;
update public.glossary_terms set sections = $g$[{"text": "- A clean bucket or container used only for the aquarium\n- A length of airline tubing\n- A plastic airline valve, or just a loose knot tied in the tubing\n- A net or cup for moving the animals at the end", "heading": "What you need"}, {"text": "- Float the sealed bag in the tank for about 15 minutes so the temperature matches.\n- Gently pour the animals and their water into the bucket, tilting it so they stay covered. Set the bucket below the tank.\n- Start a siphon through the tubing from the tank to the bucket. Adjust the valve or knot to about 2 to 4 drips per second, or slower for shrimp.\n- Let it drip until the water volume has roughly doubled, then pour off half and let it double again. This usually takes 45 to 90 minutes, and up to 2 hours or more for shrimp.\n- Net or cup the animals into the tank. Discard the bucket water; never pour shipping water into your aquarium.", "heading": "How to drip acclimate"}, {"text": "- Dripping too fast, which defeats the purpose\n- Letting the bucket get cold during a long acclimation; set it on a towel or keep the room warm\n- Leaving the drip unattended so the bucket overflows\n- Exposing shrimp to air when transferring them; scoop them in a cup with water\n\nFish that have been in a sealed bag for many hours can have a buildup of ammonia that becomes more toxic as fresh tank water raises the pH. For long shipments, some keepers skip the long drip and acclimate fish quickly, or add an ammonia binder to the bucket. This is debated, so match the method to how long the animals were in transit.", "heading": "Common mistakes"}, {"text": "Drip acclimation is best for shrimp, snails, wild-caught fish, and any animal coming from water with a very different pH or hardness than yours. For common hardy fish from a local store with similar water, floating and slowly adding tank water over 20 to 30 minutes works fine.", "heading": "When to use it"}]$g$::jsonb, faq = $g$[{"a": "Most keepers drip shrimp for 1 to 2 hours or longer, letting the water double, pouring off half and letting it double again, because they are sensitive to changes in hardness and pH.", "q": "How long should I drip acclimate shrimp?"}, {"a": "About 2 to 4 drips per second is a common target for most fish. Many keepers drip more slowly for shrimp, around 1 drip per second.", "q": "How many drips per second for drip acclimation?"}, {"a": "For sensitive animals and big differences in water chemistry, yes. For hardy fish moving between similar water, floating plus gradual water additions is usually enough.", "q": "Is drip acclimation better than floating the bag?"}]$g$::jsonb where slug = $g$drip-acclimation$g$;
update public.glossary_terms set sections = $g$[{"text": "- Swollen, rounded belly\n- Scales raised outward, giving a pinecone look when viewed from above\n- Bulging eyes\n- Pale gills and a red or swollen vent\n- Lethargy, hiding and refusing food\n- Stringy, pale feces", "heading": "Signs to watch for"}, {"text": "Fluid builds up when the kidneys or other organs stop working properly. Common triggers include bacterial infections such as Aeromonas, long-term poor water quality, chronic stress, poor diet, and old age. Because it is a symptom, two fish with dropsy may have completely different underlying problems. It is not highly contagious by itself, but the bacteria and conditions behind it can affect other fish.", "heading": "What causes it"}, {"text": "- Move the fish to a hospital tank right away to protect tankmates.\n- Add Epsom salt (magnesium sulfate, not aquarium salt) at a commonly recommended 1 to 3 teaspoons per 5 gallons to help draw out fluid.\n- Use a broad-spectrum antibacterial; medicated food with an antibiotic such as kanamycin is often recommended if the fish still eats.\n- Keep the water very clean with small daily water changes and stable temperature.\n- Feed lightly with high-quality food.\n\nIf the scales are fully raised and the fish has stopped eating, recovery is unlikely. Humane euthanasia is a kind choice if the fish is clearly suffering.", "heading": "How to treat dropsy"}, {"text": "Keep ammonia and nitrite at 0 ppm and nitrate low with regular water changes. Avoid overfeeding, give a varied, quality diet, and quarantine new arrivals. Test the main tank whenever a fish develops dropsy, since the cause there may still be affecting others.", "heading": "Preventing dropsy"}]$g$::jsonb, faq = $g$[{"a": "Some do if it is caught early, before the scales fully raise. Advanced cases with pineconing and no appetite rarely recover.", "q": "Can a fish survive dropsy?"}, {"a": "Dropsy itself is not usually contagious, but the bacteria or poor water behind it can affect other fish, so isolate the sick fish and test your tank.", "q": "Is dropsy contagious?"}, {"a": "Commonly recommended doses are about 1 to 3 teaspoons per 5 gallons in a hospital tank, starting at the low end. Dissolve it fully in tank water before adding.", "q": "How much Epsom salt should I use for dropsy?"}]$g$::jsonb where slug = $g$dropsy$g$;
update public.glossary_terms set definition = $g$Epistylis is a stalked, single-celled ciliate, usually treated as a parasite, that attaches to fish skin and fins, forming white fuzzy tufts that often lead to red sores.$g$, sections = $g$[{"text": "- Small white or gray fuzzy tufts on the body, fins or spines\n- Tufts that look like tiny cauliflower or cotton under a magnifier\n- Red, ulcer-like sores where colonies grew\n- Scratching against decor, clamped fins and lethargy\n\nIt is most common on goldfish, koi, catfish and other fish kept in warm water rich in organic waste.", "heading": "Signs to watch for"}, {"text": "Epistylis colonies are tufts of tiny stalked cells and usually sit in distinct spots, often on spines or scales. True fungus grows in long, wispy strands on wounds. Columnaris spreads across the skin as flat, matted patches and moves fast. A microscope gives the only sure answer, but tufts with red sores beneath them on otherwise healthy fish point toward epistylis. It is not an alga or fungus, so antifungal products do not help.", "heading": "Epistylis vs fungus and columnaris"}, {"text": "- Do large water changes, 30 to 50 percent, and clean the filter and gravel to cut organic waste.\n- Use an antiparasitic treatment labeled for external protozoa; formalin-based treatments are common, but epistylis can be stubborn and often needs repeat treatment.\n- Aquarium salt baths help some fish, but avoid salt with scaleless fish, sensitive plants and invertebrates.\n- Treat secondary red sores with an antibacterial if they worsen.\n- Strong aeration helps, since many treatments lower oxygen.\n\nFormalin and similar medications are hard on shrimp, snails and some plants, so treat in a hospital tank when possible.", "heading": "How to treat it"}, {"text": "Avoid overfeeding and overstocking, vacuum the substrate, and keep up weekly water changes. Ponds and goldfish tanks with heavy waste loads are most at risk, especially when water warms in summer.", "heading": "Preventing it"}]$g$::jsonb, faq = $g$[{"a": "No. It is a stalked protozoan, usually treated as a parasite, that only looks fuzzy like fungus, which is why antifungal treatments do not work on it.", "q": "Is epistylis a fungus?"}, {"a": "It takes hold in water with high organic waste, often from overfeeding, overstocking or infrequent water changes, especially in warm water.", "q": "What causes epistylis in fish?"}, {"a": "Yes. It can spread to other fish in the same water, so fix the water quality for the whole tank and watch every fish, even if you treat the worst cases in a hospital tank.", "q": "Is epistylis contagious?"}]$g$::jsonb where slug = $g$epistylis$g$;
update public.glossary_terms set sections = $g$[{"text": "- Flat, round, greenish or clear bumps about 1/8 to 3/8 inch across that can move around the body\n- Two dark eye spots visible on the parasite up close\n- Red, inflamed spots where they have fed\n- Flashing, rubbing against surfaces and jumping\n- Clamped fins, rapid breathing and lethargy", "heading": "Signs to watch for"}, {"text": "Argulus arrives on new fish, especially goldfish and koi from outdoor ponds, and sometimes on plants or in water from wild sources. Adults can leave a fish and swim freely for several days, longer in cool water. Females lay rows of eggs on hard surfaces like glass, rocks and decor, and those eggs hatch over several weeks, which is why infestations come back if you only remove the visible adults.", "heading": "How they get in"}, {"text": "- Remove visible lice with blunt tweezers. Hold the fish gently in a wet net and pull straight off; dab the spot with a disinfectant safe for fish wounds.\n- Treat the whole tank or pond with an antiparasitic product labeled for crustacean parasites like anchor worms and fish lice.\n- Repeat according to the label, often several doses spread over 3 to 4 weeks or more, to catch lice that hatch later.\n- Scrub glass and decor to remove egg clusters.\n- Watch for bacterial infections in bite wounds and treat if they appear.\n\nMedications that kill fish lice also kill other crustaceans, so they are deadly to shrimp, crayfish and some other invertebrates. Move those animals out before treating.", "heading": "How to get rid of fish lice"}, {"text": "Quarantine new pond and coldwater fish for at least 4 weeks and inspect them closely in good light. Avoid adding wild-caught plants or water to your tank. Rinse new plants and inspect them for egg clusters.", "heading": "Preventing them"}]$g$::jsonb, faq = $g$[{"a": "Yes. Adults are about 1/8 to 3/8 inch across, but they are flat and nearly see-through, so look closely in good light.", "q": "Can you see fish lice with the naked eye?"}, {"a": "Adults can swim freely for several days or longer, and their eggs survive on surfaces for weeks, so treatment must cover hatching periods.", "q": "Can fish lice live without a host?"}, {"a": "No. Argulus only feeds on fish and amphibians and does not infest people.", "q": "Are fish lice dangerous to humans?"}]$g$::jsonb where slug = $g$fish-lice$g$;
update public.glossary_terms set sections = $g$[{"text": "- Low oxygen from warm water, overcrowding or a filter that has stopped\n- Ammonia or nitrite in the water, which damages gills and blood\n- Too little surface movement, especially in heavily planted tanks overnight\n- Too much injected CO2 in planted tanks\n- Gill parasites or infections\n- Medications that reduce oxygen or irritate gills", "heading": "Common causes"}, {"text": "- Check that the filter and any air pump are running.\n- Do a 30 to 50 percent water change with dechlorinated water matched to the tank temperature.\n- Add aeration: point the filter outflow at the surface, add an air stone, or lower the water line so the outflow splashes.\n- Turn off CO2 injection if you use it.\n- Test ammonia, nitrite and temperature.\n\nIf fish perk up within minutes of extra aeration, low oxygen was the cause. If they keep gasping in well-aerated water with good test results, look for gill parasites or disease.", "heading": "What to do right away"}, {"text": "Some fish breathe air as part of normal behavior. Bettas, gouramis and paradise fish have a labyrinth organ and regularly gulp at the surface. Corydoras and some loaches dart up for a quick breath and dive back down. Watch for a change in behavior: fish that normally stay low hanging at the top together is the warning sign.", "heading": "Normal surface breathers"}, {"text": "Keep the surface moving, avoid overstocking, and clean filters regularly so flow stays strong. In summer, watch temperatures; warm water above about 82°F holds less oxygen while fish need more of it. Plant tanks with CO2 should use a timer that shuts it off before lights out.", "heading": "Preventing it"}]$g$::jsonb where slug = $g$gasping-at-surface$g$;
update public.glossary_terms set sections = $g$[{"text": "Ich, short for Ichthyophthirius multifiliis, is a single-celled parasite and the most common disease in freshwater aquariums. It shows up as white spots that look like grains of salt on the body, fins and gills. It usually arrives with new fish or plants and takes hold when fish are stressed by a temperature drop, poor water or shipping. Saltwater fish get a similar-looking but different parasite, Cryptocaryon.", "heading": "What ich is"}, {"text": "- White pinhead spots on skin, fins and gills\n- Flashing: fish scratching against rocks and decor\n- Clamped fins and rapid breathing\n- Hiding and loss of appetite", "heading": "Symptoms"}, {"text": "The spots you see are parasites buried under the skin, where medication can't reach them. Each one eventually drops off, forms a cyst on the bottom and releases hundreds to thousands of free-swimming young that hunt for a new fish. Treatment only kills that free-swimming stage, so you have to keep treating long enough to catch every generation, typically 10 to 14 days and at least 3 days after the last spot disappears.", "heading": "Why treatment takes time"}, {"text": "- Raise the temperature slowly to around 80 to 86°F if your fish tolerate it; heat speeds up the life cycle so treatment works faster. Add aeration, since warm water holds less oxygen.\n- Use an ich medication and follow the label. Many ich medications harm shrimp, snails and other invertebrates, so check the label or move them first. Remove carbon from the filter while treating.\n- Some keepers use aquarium salt instead, but scaleless fish, many plants and invertebrates don't tolerate it.\n- Vacuum the gravel to pick up cysts, and keep up with water changes.\n- Treat the whole tank, not just the fish showing spots.", "heading": "How to treat ich"}]$g$::jsonb, faq = $g$[{"a": "Yes. If one fish has it, the parasite is in the tank. Treat the whole aquarium.", "q": "Is ich contagious?"}, {"a": "Sometimes healthy fish fight off a light case, but it often explodes. Treating early is much safer.", "q": "Can ich go away on its own?"}, {"a": "Quarantine new fish for 4 to 6 weeks if you can, and at least 2, avoid sudden temperature swings and keep water quality high.", "q": "How do I prevent ich?"}]$g$::jsonb where slug = $g$ich$g$;
update public.glossary_terms set sections = $g$[{"text": "- Loss of appetite, often the first sign; the fish may take food and spit it out\n- Hiding and staying away from the group\n- Swollen belly, which shows up later\n- Rapid breathing\n- White, stringy feces\n- Red or swollen vent\n\nBy the time the belly is visibly bloated, the fish may have only a few days left without treatment.", "heading": "Signs to watch for"}, {"text": "The exact cause is debated. It is thought to involve internal bacteria or protozoa that take hold when the gut is irritated. The biggest risk factors are feeding high-protein foods such as bloodworms, beef heart or meaty pellets to herbivores like mbuna and tropheus, along with overfeeding, stress from aggression or crowding, and poor water quality.", "heading": "What causes it"}, {"text": "- Move the fish to a hospital tank right away.\n- Treat with metronidazole as soon as you notice signs. Medicated food works best if the fish still eats; otherwise dose the water following the label.\n- Some keepers combine metronidazole with an antibacterial for advanced cases.\n- Epsom salt at a commonly recommended 1 to 3 teaspoons per 5 gallons can help relieve swelling.\n- Keep the water clean and well aerated.\n\nWatch the rest of the group closely. If one fish gets it, the diet or conditions may put others at risk, and some keepers dose metronidazole food to the whole tank.", "heading": "How to treat Malawi bloat"}, {"text": "Feed mbuna and other herbivores a spirulina or vegetable-based staple, and keep meaty treats rare or skip them entirely. Feed small amounts once or twice daily, and consider one fast day a week. Keep nitrate low with weekly water changes of 30 to 50 percent, and avoid crowding beyond what your tank and filtration can handle.", "heading": "Preventing it"}]$g$::jsonb where slug = $g$malawi-bloat$g$;
update public.glossary_terms set sections = $g$[{"text": "- One or both eyes bulging noticeably from the head\n- A cloudy or white film over the bulging eye\n- A ring of white or red tissue around the eye\n- In severe cases, the eye may burst or be lost\n\nNote that some fancy goldfish, like telescope eyes, naturally have protruding eyes. Look for a change from the fish's normal look.", "heading": "Signs to watch for"}, {"text": "One eye bulging usually points to an injury, such as a collision with decor, rough netting or a fight. Both eyes bulging points to a water quality problem or a bacterial infection affecting the whole body. If pop-eye appears with a swollen belly and raised scales, it may be part of dropsy, which is much more serious.", "heading": "One eye or both"}, {"text": "- Test the water and do a 25 to 50 percent water change, then keep water pristine with regular changes.\n- Move the fish to a hospital tank if you plan to medicate.\n- Add Epsom salt at a commonly recommended 1 to 3 teaspoons per 5 gallons to help reduce swelling.\n- For both-eye cases or signs of infection, use a broad-spectrum antibacterial according to the label.\n- Remove sharp decor and separate aggressive tankmates if it was an injury.\n\nSwelling usually goes down over one to several weeks. Eyes that are badly damaged may stay cloudy or be lost, but fish adapt well to living with one eye.", "heading": "How to treat pop-eye"}, {"text": "Keep ammonia and nitrite at 0 ppm and nitrate low. Choose smooth decor, net fish gently, and avoid housing aggressive fish with peaceful ones. Quarantine new fish to keep bacterial infections out.", "heading": "Preventing it"}]$g$::jsonb where slug = $g$pop-eye$g$;
update public.glossary_terms set body = $g$Often deadlier and faster-moving than ich, velvet attacks the gills first and is best caught early. Treatment typically involves medication and dimming the lights, since the parasite gets part of its energy from light.$g$ where slug = $g$velvet$g$;
update public.glossary_terms set sections = $g$[{"text": "- Bristlenose and other algae-eating plecos\n- Otocinclus, though many are shy about wafers at first\n- Corydoras and other catfish\n- Shrimp and snails\n- Many loaches, mollies and other grazers\n\nNot every pleco is a vegetarian. Clown, zebra and many other plecos need more protein or wood, so check what your species really eats.", "heading": "Who eats them"}, {"text": "Drop wafers in after lights go out for nocturnal fish like plecos, or near their favorite hiding spot. A common starting point is one wafer per pleco, or a quarter wafer for a small group of shrimp, every other day. Break wafers into pieces for small fish and shrimp so they do not sit uneaten.\n\nWafers soften slowly and stay intact for hours, so they can be grazed over time. Remove anything left after 12 to 24 hours, or sooner in small shrimp tanks, to keep it from fouling the water.", "heading": "How to feed them"}, {"text": "Read the ingredient list. Many wafers list fish meal or wheat first, with only a small amount of algae. For true herbivores, look for spirulina, kelp or other algae near the top of the list. Protein-rich wafers suit omnivores like corydoras. Rotating two or three foods covers more nutritional needs than relying on one.", "heading": "Choosing a good wafer"}, {"text": "- Assuming algae eaters can live on tank algae alone; most need supplemental food\n- Overfeeding, which leads to ammonia spikes and snail booms\n- Feeding during the day when faster fish eat them first\n- Using wafers as the only food instead of adding blanched vegetables and other variety", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$algae-wafer$g$;
update public.glossary_terms set sections = $g$[{"text": "- Zucchini and cucumber, the most popular choices\n- Spinach and romaine lettuce\n- Shelled peas, a favorite of goldfish\n- Green beans, kale and broccoli\n- Sweet potato and carrot, cooked until soft\n\nAvoid onions, garlic in large amounts, spicy peppers, citrus and anything seasoned or cooked with oil or salt. Spinach is high in oxalates, so feed it as an occasional treat rather than daily.", "heading": "Best vegetables to try"}, {"text": "- Wash vegetables well and peel cucumber or zucchini to reduce pesticide residue.\n- Cut into slices about 1/4 inch thick, or into fish-sized bites.\n- Drop into boiling water for 1 to 2 minutes for soft vegetables like zucchini and spinach, or longer for carrots and sweet potato.\n- Move to cold water to stop cooking.\n- Let cool completely before feeding.\n\nPeas need the shell removed after cooking. Extra slices can be frozen and thawed for later feedings.", "heading": "How to blanch them"}, {"text": "Most vegetables float at first. Weigh slices down with a stainless steel fork, a clean rock, or a plastic vegetable clip. Plecos and other nocturnal grazers do best if you add vegetables in the evening.\n\nStart with a small piece and watch how fast it disappears. Remove leftovers within 12 to 24 hours, before they go mushy and pollute the water. Offering vegetables two or three times a week works well for most herbivores.", "heading": "How to feed them"}, {"text": "- Leaving vegetables in too long, which leads to cloudy water and ammonia\n- Feeding unwashed vegetables that may carry pesticides, which are deadly to shrimp\n- Overfeeding vegetables to carnivorous fish that cannot digest them well", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$blanched-vegetables$g$;
update public.glossary_terms set sections = $g$[{"text": "Frozen bloodworms are the best all-round choice. Freezing keeps most of the nutrition, and commercially frozen worms are cleaned and often treated to reduce pathogens, so they carry less disease risk than live worms. Thaw a cube in a cup of tank water, then pour off the melt water, which is full of dissolved juices that pollute the tank.\n\nFreeze-dried worms are convenient and shelf stable but swell in the gut, so soak them for a few minutes before feeding. Live bloodworms are the most exciting for fish but are usually harvested from the wild and carry the highest risk of bringing in disease.", "heading": "Frozen, freeze-dried or live"}, {"text": "Two or three bloodworm meals a week is plenty for most community tanks. Feed only what the fish finish in about two minutes and siphon out any worms that sink into the gravel, because they rot quickly and spike ammonia. For fish like bettas, a few worms per feeding is a full meal.\n\nWatch for bloating after a bloodworm meal, especially in bettas and goldfish. A swollen belly that lasts more than a day is a cue to fast the fish and cut back.", "heading": "How much and how often"}, {"text": "- Great for: bettas, gouramis, cichlids, loaches, corydoras, killifish and most predatory species\n- Use sparingly for: herbivores like mbuna, which can bloat on rich protein\n- Good for: wild-caught or stubborn fish that refuse prepared foods", "heading": "Who should eat them"}, {"text": "Some people develop skin or breathing allergies after handling bloodworms often. Use tweezers or a feeding cone, wash your hands afterward and keep frozen packs in the freezer until use so they don't thaw and refreeze.", "heading": "Handling tips"}]$g$::jsonb where slug = $g$bloodworms$g$;
update public.glossary_terms set sections = $g$[{"text": "- Fill a bottle or hatchery with about 1 liter of water and 1.5 to 2 tablespoons of salt\n- Add about half a teaspoon of eggs (cysts)\n- Run an airline to the bottom so the eggs keep tumbling\n- Keep it at 80 to 82°F with light on it\n- Harvest in 18 to 24 hours", "heading": "How to hatch baby brine shrimp"}, {"text": "Turn off the air and let it sit for 5 to 10 minutes. The empty shells float, unhatched eggs sink, and the orange babies gather near a light at the bottom. Siphon them out, rinse them in fresh water through a fine net, and feed. Avoid feeding shells, which can block fry guts.\n\nBaby brine shrimp start losing nutrition within about 12 hours, so hatch small batches daily. They live only a few hours in freshwater, so feed amounts the fry can clean up.", "heading": "Harvesting and feeding"}, {"text": "Frozen adults are a good occasional treat for community fish and are easy to portion. On their own they are lighter in nutrition than baby brine shrimp or mysis, so they work best mixed into a rotation. Enriched or gut loaded versions offer more value. Thaw and rinse before feeding.\n\nLive adult brine shrimp are sold at some stores and are a great treat for predators and picky fish. Rinse them first, since they come in salt water.", "heading": "Frozen and adult brine shrimp"}, {"text": "Decapsulated eggs have the hard shell removed chemically. They can be fed directly to small fry without hatching and hatch a bit more reliably, with no shells to separate.", "heading": "Decapsulated eggs"}]$g$::jsonb, faq = $g$[{"a": "Usually only a few hours. Feed what your fry can eat quickly so dead shrimp don't foul the water.", "q": "How long do baby brine shrimp live in freshwater?"}, {"a": "Baby brine shrimp are excellent nutrition, especially for fry. Adult brine shrimp are a fine treat but shouldn't be the main diet.", "q": "Are brine shrimp good for fish?"}, {"a": "The usual causes are water that is too cold, old or poorly stored eggs, too little salt or not enough aeration. Aim for 80 to 82°F with strong bubbling.", "q": "Why are my brine shrimp not hatching?"}]$g$::jsonb where slug = $g$brine-shrimp$g$;
update public.glossary_terms set sections = $g$[{"text": "In the wild, carnivores eat insects, larvae, worms, crustaceans and in some cases other fish. In the aquarium, the base of the diet should be a high-protein pellet or flake made mostly from fish, shrimp or insect meal. Add frozen bloodworms, brine shrimp, mysis, krill or chopped seafood a few times a week for variety.\n\nFeed most adult carnivores once a day, or every other day for large predators, in an amount they finish in a couple of minutes. Overfeeding meaty foods is a fast route to fatty livers and dirty water.", "heading": "What carnivores eat"}, {"text": "- Bettas and many killifish, which hunt insects at the surface\n- Many larger cichlids, such as oscars and peacock bass\n- Many pufferfish, which need hard-shelled foods like snails to wear down their beaks\n- Arowanas, bichirs and other large predators\n- Leaf fish and other ambush hunters, which often only take live or moving food", "heading": "Examples in the hobby"}, {"text": "Live feeder goldfish and rosy reds are cheap but often carry parasites and disease, and both contain thiaminase, an enzyme that breaks down vitamin B1 and can cause deficiencies with long-term use. Most carnivores can be trained onto frozen and prepared foods, which are safer and more complete. If you do feed live fish, quarantine and gut load them first.", "heading": "Feeder fish: think twice"}, {"text": "A good rule is that anything that fits in a carnivore's mouth may become food, including shrimp and small tetras. Protein-heavy diets also produce more waste, so carnivore tanks usually need stronger filtration and regular water changes.", "heading": "Tankmates and waste"}]$g$::jsonb where slug = $g$carnivore$g$;
update public.glossary_terms set body = $g$Daphnia are small enough for nano fish and juvenile fry, they trigger natural hunting behavior and their shells add roughage that helps keep digestion moving. Live daphnia also survive in freshwater until eaten, so uneaten ones don't quickly rot and can even help clear green water.$g$, sections = $g$[{"text": "Daphnia are a popular remedy for constipation and mild bloating, especially in bettas and fancy goldfish. The tough outer shell (exoskeleton) acts as fiber. They are also a gentle food for fussy or newly imported fish, and they work well for small species like rasboras and killifish. For very tiny fish such as chili rasboras, use young daphnia or a smaller species like moina, since adult daphnia can be too big.", "heading": "Why fish keepers use them"}, {"text": "- Use a container of 5 gallons or more, ideally a tub outdoors in mild weather\n- Fill with dechlorinated water and keep it between 60 and 75°F\n- Feed green water, spirulina powder or a pinch of active dry yeast every few days\n- Add little or no aeration, only very gentle bubbles if any\n- Harvest about a quarter of the population with a fine net a few times a week\n- Do partial water changes to keep the culture from crashing", "heading": "How to culture daphnia"}, {"text": "Rinse live daphnia in a net before adding them so you don't pour in culture water. Feed them two or three times a week as a treat. Frozen daphnia are lighter in nutrition but still useful for fiber. Outdoor cultures can pick up insect larvae, so check before feeding them to a shrimp tank or fry tank.\n\nIf a fish bloats after a rich meal, a day of fasting followed by daphnia is the usual first step. A fish that eats daphnia and still doesn't pass waste within a couple of days may have something more serious going on than simple constipation.\n\nDaphnia cultures are sensitive to soap, chlorine and pesticides, so always use dechlorinated water and clean tools.", "heading": "Feeding tips"}]$g$::jsonb, faq = $g$[{"a": "Many keepers use them for that. The shell provides roughage, so fasting a day and then feeding daphnia is a common first step for a bloated fish.", "q": "Do daphnia help with constipation in fish?"}, {"a": "Yes. They survive well in freshwater until eaten, though a filter intake will pull some in over time, which makes them one of the cleanest live foods to use.", "q": "Can daphnia live in a fish tank?"}, {"a": "Yes, daphnia do not harm shrimp. They compete a little for the same tiny food, but they are a safe addition.", "q": "Are daphnia safe for shrimp tanks?"}]$g$::jsonb where slug = $g$daphnia$g$;
update public.glossary_terms set faq = $g$[{"a": "It is strongly recommended. Thawing lets you drain off the liquid and keeps fish from swallowing hard, cold pieces.", "q": "Do you have to thaw frozen fish food?"}, {"a": "Two to four times a week is typical, alongside a dry staple. Some keepers feed it daily to picky or carnivorous species.", "q": "How often should I feed frozen food?"}, {"a": "It is usually safer, since freezing kills many parasites, though not all bacteria, and it is easier to store. Live food is a bit more stimulating and slightly fresher in nutrition.", "q": "Is frozen food better than live food?"}]$g$::jsonb where slug = $g$frozen-food$g$;
update public.glossary_terms set sections = $g$[{"text": "Feed the prey a rich food for 6 to 24 hours before you use it. For adult brine shrimp, use spirulina powder, green water, or a commercial enrichment with fatty acids and vitamins. For blackworms and other worms, a pinch of crushed flake or algae wafer works. Feeder insects take fresh greens and crushed fish pellets.\n\nVitamin and omega-3 enrichment is especially helpful for marine fish and for fish being conditioned to spawn. Keep the enrichment water aerated so the prey stay alive while they feed, and use only a small amount of food so the container doesn't foul.", "heading": "How to gut load"}, {"text": "The two terms overlap. Gut loading usually means giving prey a good meal so its stomach is full. Enrichment usually means soaking very small prey, like baby brine shrimp, in a product rich in omega-3 fatty acids and vitamins for a few hours. Both aim for the same result: a more nutritious bite.", "heading": "Gut loading vs enrichment"}, {"text": "If you must feed live fish to a predator, quarantine them first and feed them a quality flake for several days. Many feeder fish arrive starved and sick. Gut loading improves their value, but it does not remove the disease risk, so frozen and prepared foods are still the safer choice for most predators.", "heading": "Feeder fish"}, {"text": "- Use prey within a day of gut loading, before the food passes through\n- Rinse prey before feeding so the gut-loading food doesn't cloud the tank\n- Don't overcrowd prey containers, or they die before feeding time", "heading": "Tips"}]$g$::jsonb where slug = $g$gut-loading$g$;
update public.glossary_terms set sections = $g$[{"text": "- Many mbuna cichlids from Lake Malawi, which graze algae off rocks\n- Many plecos, such as bristlenose, which rasp algae and biofilm off rock and wood\n- Silver dollars, which eat most aquarium plants\n- Tropheus cichlids from Lake Tanganyika, which are also prone to bloat\n- Some goodeids\n- Otocinclus, which graze soft algae and biofilm", "heading": "Examples"}, {"text": "Base the diet on a spirulina or vegetable flake or pellet. Add blanched vegetables two to three times a week: zucchini, cucumber, spinach, shelled peas and romaine are common choices. Blanch them in boiling water for a minute or two to soften them, weigh them down with a fork or veggie clip and remove leftovers within 24 hours so they don't rot.\n\nSpirulina-based flakes and algae wafers are the easiest daily staple. Feed small amounts two or three times a day for grazers like mbuna, which naturally eat little and often, instead of one big meal.\n\nLeftover vegetables cloud water quickly in warm tanks, so pull them out by the next morning.", "heading": "What to feed"}, {"text": "Malawi bloat is a serious illness linked to rich, high-protein foods in mbuna. Avoid feeding them bloodworms or beef heart. Even herbivores accept a little animal protein, but it should stay a small part of the diet.", "heading": "Protein and bloat"}, {"text": "Many herbivores will eat soft-leaved plants. Tough plants like anubias, java fern and bolbitis usually survive, while vallisneria and stem plants often disappear. Some keepers simply accept that a herbivore tank will be decorated with rock and wood.", "heading": "Plants in the tank"}]$g$::jsonb where slug = $g$herbivore$g$;
update public.glossary_terms set sections = $g$[{"text": "- Baby brine shrimp: classic first food for fry\n- Microworms and vinegar eels: tiny, easy to culture, great for very small fry\n- Daphnia: small fish and fiber for digestion\n- Blackworms: rich and loved by loaches, cories and bettas\n- Mosquito and glass worm larvae: excellent for conditioning\n- Feeder fish: only for predators, and best avoided when possible", "heading": "Popular live foods"}, {"text": "Live foods collected from ponds can bring in parasites, leeches, hydra or predatory insect larvae. Blackworms and tubifex from dirty sources can carry bacteria. Feeder fish are the biggest risk and often arrive sick. Cultured foods such as brine shrimp, microworms and home-raised daphnia are much safer.", "heading": "Risks to know"}, {"text": "Rinse live food in a net with clean water before feeding. Feed amounts that will be eaten within a few minutes, except prey like daphnia that survive in the tank. For breeding, feeding live food daily for a week or two often brings fish into spawning condition.\n\nMany breeders pair a week of live food with a slightly cooler water change to trigger spawning in species like corydoras. Feed the culture you plan to use a day ahead so the prey is well fed and more nutritious when it reaches your fish.", "heading": "Using live food well"}, {"text": "Most live food cultures are cheap and simple. A small tub of oatmeal seeded with a starter culture grows microworms, a bottle and an airline hatches brine shrimp and a tub outdoors grows daphnia. Keep two cultures of each so one crash doesn't leave you without food.", "heading": "Culturing at home"}]$g$::jsonb where slug = $g$live-food$g$;
update public.glossary_terms set sections = $g$[{"text": "- Daily: a quality omnivore flake or micro pellet as the staple\n- Two or three times a week: frozen brine shrimp, daphnia, mysis or bloodworms\n- Once or twice a week: a spirulina food or blanched vegetables\n- One day a week: no food at all\n\nFeed small amounts once or twice a day, enough to be eaten in about two minutes.\n\nVariety matters more than any single premium food. A cheap, decent flake rotated with frozen foods and greens usually beats an expensive food fed alone every day. Change foods gradually if your fish are fussy, mixing a little of the new food with the old.", "heading": "A simple feeding plan"}, {"text": "Omnivores are a spectrum. Mollies and many barbs lean toward plants and algae and benefit from regular spirulina. Gouramis and many cichlids lean toward meaty foods. Check what your species eats in the wild and shift the balance a little in that direction.", "heading": "Leaning one way or the other"}, {"text": "In a community tank, different fish eat at different levels. Use a floating food for surface feeders, a slow-sinking food for mid-water fish and a sinking wafer or pellet for bottom dwellers like corydoras. Feed bottom dwellers after lights out if faster fish steal everything.", "heading": "Feeding mixed tanks"}, {"text": "Faded color, thin bellies and constant grazing on plants can all point to an unbalanced or too-small diet. Bloated bellies can mean too much rich protein. Long, stringy white waste that lasts more than a few days can point to internal parasites or other illness rather than diet, so look into it.", "heading": "Signs the diet is off"}]$g$::jsonb where slug = $g$omnivore$g$;
update public.glossary_terms set body = $g$Your first fish shape whether the hobby feels fun or frustrating. Hardy species survive the learning curve of water changes, feeding and cycling, and they help you build good habits before you try sensitive fish. Even beginner fish still need a cycled tank, the right tank size and a heater for tropical species.$g$, sections = $g$[{"text": "- Platies, mollies and swordtails: colorful livebearers that eat anything; mollies do best in harder water\n- Zebra and leopard danios: very tough, active, best in groups of 6 or more\n- White Cloud Mountain minnows: unheated tanks around 64 to 72°F\n- Corydoras catfish: peaceful bottom dwellers, kept in groups\n- Harlequin rasboras and many tetras: once the tank is fully cycled\n- A single betta: in 5 gallons or more with a heater", "heading": "Good choices for a first tank"}, {"text": "Common plecos grow to over 12 inches. Goldfish are hardy but get large and very messy, needing much more space than a small bowl. Oscars and other big cichlids outgrow most starter tanks quickly. Bala sharks and iridescent sharks are schooling fish that reach a foot or more. Always check adult size before buying.\n\nAlso be wary of fish that need very specific water. Discus, wild bettas, many Caridina shrimp and most saltwater species are best left until you have experience.", "heading": "Fish that are often sold to beginners but shouldn't be"}, {"text": "Cycle the tank before adding fish, or use a fish-in cycle with a few hardy fish and daily testing. Add fish a few at a time over several weeks so the beneficial bacteria can keep up. A 20 to 30 gallon tank is actually easier than a tiny one, because water quality stays more stable.", "heading": "Setting yourself up to succeed"}, {"text": "Once you have kept a tank stable for a few months, you can try more sensitive fish like cardinal tetras, apistogrammas or shrimp.", "heading": "Next steps"}]$g$::jsonb where slug = $g$beginner-fish$g$;
update public.glossary_terms set sections = $g$[{"text": "- 10 to 20 gallons: a betta or a honey or dwarf gourami\n- 20 to 40 gallons: a pair of German blue rams, a pair of apistogrammas, a pair of kribensis or, toward the upper end, a pearl gourami\n- 40 to 75 gallons: angelfish, a group of rainbowfish, or a bristlenose pleco with character\n- 75 gallons and up: a group of discus, a severum, or a larger peaceful cichlid", "heading": "Popular choices by tank size"}, {"text": "Check the adult size, not the size in the store. Make sure the fish fits your water: discus and rams want warm, soft water, roughly 80 to 86°F, while many rainbowfish are fine in harder water. Consider personality too. Gouramis and cichlids interact with their keepers, which is part of the appeal.", "heading": "How to choose"}, {"text": "Build the community around the centerpiece. Avoid fin nippers like tiger barbs with long-finned fish such as angelfish and bettas. Remember that angelfish will eat small fish like neon tetras as they grow. Pick dither fish, such as a school of medium tetras or rasboras, that are too big to be eaten and calm enough not to stress the main fish.\n\nAdd the centerpiece last when possible, after the dither fish have settled, so it isn't the only fish in the tank while you finish stocking.", "heading": "Planning tankmates"}, {"text": "Some centerpiece species, like many gouramis, fight with their own kind in small tanks. Others, like angelfish or discus, do better in groups. Research before deciding whether to buy one or several.", "heading": "One or several?"}]$g$::jsonb, faq = $g$[{"a": "A honey or dwarf gourami, a betta or, in a 20 long, a pair of German blue rams are common choices for a 20 gallon community.", "q": "What is a good centerpiece fish for a 20 gallon tank?"}, {"a": "Sometimes, if they are compatible and the tank is big enough. Two male gouramis or two territorial cichlids in a small tank often fight.", "q": "Can you have two centerpiece fish?"}, {"a": "Yes, they are a classic choice, with about 30 gallons as a minimum for a single fish or pair and more room for a group, but they will eat small fish like neon tetras.", "q": "Are angelfish good centerpiece fish?"}]$g$::jsonb where slug = $g$centerpiece-fish$g$;
update public.glossary_terms set sections = $g$[{"text": "- Open the box as soon as it arrives, in dim light\n- Photograph or video the sealed bags before opening them, showing any dead animals clearly\n- Note the time and contact the seller within their deadline, often 2 hours to the same day\n- Float and acclimate survivors right away; don't wait on paperwork", "heading": "What to do when a box arrives"}, {"text": "Most sellers offer a live arrival guarantee, but terms vary. Many require you to be home for delivery, to choose overnight or express shipping and to send clear photos of the unopened bag. Some only credit the cost of the animal, not shipping. Read the policy before you buy. Weather holds are common: sellers often won't ship when temperatures along the route are near or below freezing or above about 90°F, and each seller sets its own limits.", "heading": "Live arrival guarantees"}, {"text": "Long delays, temperature swings, ammonia buildup in the bag and low oxygen are the main causes. Fish that seem fine on arrival but die in the first few days can be victims of ammonia shock during acclimation: once the bag is opened, the pH rises and the ammonia that built up in the bag becomes more toxic. Don't release bag water into your tank, and don't spend hours acclimating fish sitting in high ammonia.\n\nBuy from sellers with good reviews who list their shipping methods clearly, and avoid ordering right before a holiday or weekend when packages can sit in transit an extra day or two.", "heading": "Why fish die in shipping"}, {"text": "If you ship fish yourself, fast the fish for a day or two first, use breather bags or plenty of oxygen, insulate the box and add heat or cold packs for the season.", "heading": "Selling on a marketplace"}]$g$::jsonb where slug = $g$doa$g$;
update public.glossary_terms set sections = $g$[{"text": "- Livebearers: males have a gonopodium, a rod-like anal fin used for mating, while females have a fan-shaped anal fin\n- Bettas and gouramis: males are usually more colorful with longer fins; female bettas often show a white egg spot\n- Corydoras: females are rounder and larger when viewed from above\n- Tetras and rasboras: females are usually plumper; males slimmer and brighter\n- Cichlids: males often have longer, pointed dorsal and anal fins and brighter color", "heading": "Common clues"}, {"text": "Female cherry shrimp are larger, more colorful and show a yellow or green saddle of developing eggs behind the head. Mystery snails can be sexed by gently tipping the snail and looking under the right side of the shell opening for the male's sheath, while many pest snails like ramshorns and bladder snails are hermaphrodites.", "heading": "Shrimp and snails"}, {"text": "Juveniles of most species look alike until they mature. Some fish, like many plecos and angelfish, are hard to sex reliably outside of breeding. In those cases, buying a group of 6 juveniles and letting pairs form naturally is a common approach. Venting, checking the genital papilla, is used by breeders but takes practice.", "heading": "When sexing is hard"}, {"text": "For livebearers, keep at least 2 to 3 females per male. Many tetras and rasboras school well in mixed groups.\n\nFor cichlids, gouramis and bettas, too many males in a small tank often leads to fighting. Keep one male or one bonded pair unless the tank is large with plenty of territory. Shrimp colonies work well with roughly equal numbers, since a healthy female can carry a new clutch roughly every month or two.", "heading": "Getting ratios right"}]$g$::jsonb where slug = $g$sexing$g$;
update public.glossary_terms set definition = $g$Amano shrimp (Caridina multidentata) are hardy, translucent freshwater shrimp that grow to about 1.5 to 2 inches, with females largest and are prized for eating algae and leftover food.$g$, faq = $g$[{"a": "Females carry eggs and the larvae hatch in freshwater, but the larvae need brackish water to survive, so they almost never breed in a normal tank.", "q": "Do Amano shrimp breed in freshwater?"}, {"a": "A common guide is one per 2 to 5 gallons, depending on how much algae you need them to handle.", "q": "How many Amano shrimp should I get?"}, {"a": "Rarely. They mostly eat algae and decaying plant matter, but hungry Amanos can shred very soft plants and moss, so feed them if algae runs low.", "q": "Will Amano shrimp eat my plants?"}]$g$::jsonb where slug = $g$amano-shrimp$g$;
update public.glossary_terms set definition = $g$Assassin snails (Anentome helena, formerly Clea helena) are small, striped yellow and brown freshwater snails that hunt and eat other snails, making them a natural pest snail control.$g$, body = $g$When bladder, ramshorn or Malaysian trumpet snails explode in a tank, assassin snails offer a slow but chemical-free fix that won't harm fish, plants or healthy adult shrimp. They breed slowly and only lay single eggs, so they don't become a new pest themselves.$g$, sections = $g$[{"text": "Assassin snails track prey by scent, then use a long proboscis to eat the snail inside its shell. They work best on small and medium snails. One assassin may eat a snail every few days, so expect a visible drop over several weeks to a few months, not overnight. A rough starting point is 1 assassin per 5 to 10 gallons for a heavy outbreak, fewer for a light one.", "heading": "How they control pests"}, {"text": "- Temperature: 72 to 82°F\n- pH: about 7.0 to 8.0, with moderate to hard water to keep shells strong\n- Substrate: sand or fine gravel, since they like to burrow\n- Diet: snails first, then leftover food, sinking pellets and frozen bloodworms\n- Size: about 0.75 to 1 inch", "heading": "Care basics"}, {"text": "They are safe with fish and adult shrimp. They may occasionally scavenge shrimp eggs or very weak shrimplets, but most shrimp keepers find them low risk. They will eat snails you want to keep, including small nerites and baby mystery snails, so think before adding them to a tank with prized snails.", "heading": "Will they harm anything else?"}, {"text": "They need both a male and a female and lay single eggs in small capsules on hard surfaces. Babies stay buried in the substrate for weeks to months. Numbers stay modest, especially once pest snails run out.\n\nOnce pest snails are gone, feed them a sinking pellet or frozen food a few times a week. Remove extra assassins or give them away if you don't want them hunting your nerites.", "heading": "Breeding"}]$g$::jsonb where slug = $g$assassin-snail$g$;
update public.glossary_terms set definition = $g$Caridina is a large genus of freshwater shrimp; in the hobby the name usually means dwarf shrimp like crystal red, crystal black, bee, taiwan bee and tiger shrimp, which need soft, acidic water.$g$, sections = $g$[{"text": "- pH: about 5.8 to 6.8 for crystal and bee shrimp\n- GH: about 4 to 6\n- KH: 0 to 1\n- TDS: about 100 to 160 ppm\n- Temperature: 68 to 74°F, rarely above 76°F\n\nTiger shrimp tolerate a bit more range, but stable soft water still suits them best. Amano shrimp also belong to Caridina but are far more adaptable and do fine in ordinary tap water, so these numbers don't apply to them.", "heading": "Water parameters"}, {"text": "Most keepers use an active buffering soil substrate that holds pH low, plus reverse osmosis (RO) or RO/DI water remineralized with a GH-only product made for Caridina. Tap water is usually too hard. A sponge filter keeps babies safe. Let the tank cycle fully, often 4 to 6 weeks with buffering soil, which can leach ammonia at first.", "heading": "Setting up a Caridina tank"}, {"text": "Feed lightly, a few times a week, and remove leftovers within a few hours. Good biofilm and leaf litter matter. Do small, steady water changes of about 10 percent with water matched closely for TDS and temperature, since sudden swings can cause failed molts. Active soils lose buffering over 1 to 2 years and need replacing.\n\nWatch for early warning signs: shrimp swimming frantically, hiding all day or dying around molts. Test TDS, GH and temperature first, since small shifts cause most Caridina problems. Many breeders keep a log of every water change and parameter reading.", "heading": "Feeding and maintenance"}, {"text": "Different Caridina types like crystal and taiwan bee can interbreed, which some breeders do on purpose. Caridina and Neocaridina won't crossbreed, but they need very different water, so they don't share a tank well.", "heading": "Mixing with other shrimp"}]$g$::jsonb where slug = $g$caridina-shrimp$g$;
update public.glossary_terms set sections = $g$[{"text": "- Tank: 5 gallons or more, cycled and stable for at least a few weeks\n- Temperature: 65 to 80°F, around 72 to 76°F is ideal\n- pH: about 6.5 to 8.0\n- GH: about 6 to 8; KH: about 2 to 8\n- Size: about 1 to 1.5 inches\n- Lifespan: around 1 to 2 years", "heading": "Care basics"}, {"text": "They graze biofilm and soft algae all day. Add a small amount of shrimp food, blanched spinach or crushed algae wafer a few times a week, and remove leftovers within a few hours. Overfeeding is a common reason colonies crash.", "heading": "Feeding"}, {"text": "A healthy colony breeds on its own. Females carry eggs for about 3 to 4 weeks, and babies hatch fully formed. Moss, plants and a sponge filter or pre-filter keep the young safe. Selectively bred colors tend to revert toward wild brown over generations, so many keepers remove dull shrimp to keep colors strong.", "heading": "Breeding"}, {"text": "Small, peaceful fish like otocinclus, chili rasboras and pygmy corydoras work best. Most other fish, including bettas and many tetras, will eat babies and sometimes adults. Copper in medications and snail treatments is deadly to shrimp, and some plant fertilizers contain more than trace amounts, so check every product. Acclimate new shrimp slowly, by drip if possible, over 1 to 2 hours.\n\nColors range from red to yellow, orange, blue, green and black. Mixing color lines produces wild-type brown babies over time, so keep one color per tank if you want them to stay bright.", "heading": "Tankmates and dangers"}]$g$::jsonb where slug = $g$cherry-shrimp$g$;
update public.glossary_terms set sections = $g$[{"text": "Shrimp and snails need a tiny amount of copper, since their blood pigment (hemocyanin) is built around it, but they absorb dissolved metals through their gills and skin, and excess copper damages gills and other tissues. Levels as low as a few hundredths of a ppm (often cited around 0.03 to 0.1 ppm) can kill sensitive dwarf shrimp, while copper medications are commonly dosed at roughly 0.15 ppm or more, and some products far higher. Losses can be sudden, or they can show up slowly as failed molts, lethargy and snails that stay sealed in their shells.\n\nFish are not fully immune either. Copper is a deliberate poison used at a dose fish barely tolerate, which is why it is measured and used in bare quarantine tanks.", "heading": "Why copper is so dangerous"}, {"text": "- Fish medications for ich, velvet and other parasites (check the label for copper sulfate or chelated copper)\n- Some liquid plant fertilizers, though most list copper in tiny amounts considered shrimp safe\n- Water that sits in copper pipes, especially the first draw in the morning\n- Painted or metal decorations and coins dropped into a tank\n- Substrate, rock or equipment that previously held a copper treatment", "heading": "Where copper sneaks in"}, {"text": "Read every ingredient list before dosing an invert tank. Treat sick fish in a separate hospital tank whenever you can. Run the tap for 30 seconds to a minute before filling buckets if your home has copper plumbing.\n\nIf copper has already been used, remove it with fresh activated carbon or a metal-absorbing resin and do several large water changes. Silicone, gravel and decor can slowly release copper back into the water, so many keepers never move gear from a copper-treated tank into a shrimp tank.", "heading": "How to protect invertebrates"}, {"text": "Shrimp may swim erratically, flip on their backs, lose color or die in large numbers within a day. Snails often retract and stop moving. A home copper test kit can confirm the problem, and the fix is the same: stop the source, run carbon and change water.", "heading": "Signs of copper poisoning"}]$g$::jsonb where slug = $g$copper-sensitivity$g$;
update public.glossary_terms set sections = $g$[{"text": "Detritus worms are annelids, relatives of earthworms, usually 0.25 to 1 inch long, thin and white to light brown. They wiggle in an S shape and mostly stay hidden in gravel, sand and filter sponges. People often confuse them with planaria, but detritus worms have no flat arrow-shaped head and no eyespots.", "heading": "What they look like"}, {"text": "They don't bite, don't carry fish diseases and don't eat plants. Most tanks with food going into them have some, and many fish happily snack on them.\n\nThe problem is what a population boom says about the tank. Lots of worms means lots of uneaten food and rotting waste, which also means higher ammonia and nitrate. Worms often leave the substrate and swim in open water when oxygen in the gravel drops, so a sudden swarm can also point to poor oxygen or a water-quality problem.", "heading": "Harmful or harmless"}, {"text": "- Feed less, only what fish finish in about 1 to 2 minutes\n- Vacuum the substrate during water changes, focusing on dead spots\n- Rinse filter sponges in old tank water when they clog\n- Remove dead plant leaves and any dead animals quickly\n- Keep fish that forage on the bottom, like corydoras, which pick them off\n\nOnce food supply drops, numbers fall on their own within a few weeks.", "heading": "How to reduce them"}, {"text": "Dewormers like fenbendazole are sometimes used and may reduce detritus worms, but results vary, they kill snails and they should be used with care in shrimp tanks. Since the worms are harmless, treating the cause is almost always the better choice.", "heading": "Should you use chemicals"}]$g$::jsonb where slug = $g$detritus-worms$g$;
update public.glossary_terms set sections = $g$[{"text": "Dragonfly and damselfly eggs or tiny nymphs come in on aquatic plants, especially pond-grown or outdoor-farmed plants, and sometimes in live foods or collected wild water. Tanks and tubs kept outdoors can also get eggs laid directly in them.", "heading": "How they get in"}, {"text": "Dragonfly nymphs are brown, green or gray, chunky, with six legs and large eyes, usually 0.5 to 2 inches long. Damselfly nymphs are slimmer with three leaf-like gills at the tail. Both move slowly along plants and decor, then strike with a hinged lower jaw that shoots out to grab prey.\n\nTypical signs are shrimp or fry vanishing over weeks, small fish with bite wounds, and an odd bug lurking in moss or plant thickets.", "heading": "How to recognize one"}, {"text": "- Catch it with a net or tweezers; it won't fight back much\n- Search plant thickets, moss and hardscape at night with a flashlight when they are active\n- Check the filter intake sponge and any prefilter\n- Look for shed exoskeletons, which show a nymph is living and growing in the tank, and keep searching in case there is more than one\n\nChemical treatments that would kill a nymph would also kill shrimp and snails, so manual removal is the standard approach.", "heading": "Removing them"}, {"text": "Quarantine new plants for a couple of weeks in a separate container and inspect them closely. Many keepers dip plants in a mild bleach or alum solution, or buy lab-grown tissue-culture plants, which arrive free of pests.", "heading": "Keeping them out"}]$g$::jsonb, faq = $g$[{"a": "Yes. Larger nymphs can catch fish up to about their own body length, and they readily eat shrimp and fry.", "q": "Will a dragonfly nymph eat my fish?"}, {"a": "Depending on species, a nymph can live underwater for a few months to several years before it tries to climb out and become an adult.", "q": "How long can a dragonfly nymph live in an aquarium?"}, {"a": "Usually as an egg or tiny nymph on new plants or in live food. Quarantining and inspecting plants prevents most cases.", "q": "How did a dragonfly nymph get in my tank?"}]$g$::jsonb where slug = $g$dragonfly-nymph$g$;
update public.glossary_terms set sections = $g$[{"text": "Hydra are 0.1 to 0.5 inch long, white, tan or green, with a body stuck to a surface and 4 to 12 thread-like tentacles waving at the top. They contract into a small blob when disturbed. They reproduce by budding, so one can turn into dozens in a couple of weeks when food is plentiful.", "heading": "What hydra look like"}, {"text": "They come in on plants, decor, live food and even water from a store. A few hydra can stay unnoticed for months. They multiply fast when there is lots of tiny food in the water column, such as baby brine shrimp, powdered fry food or crushed flakes left floating.", "heading": "How they get in and why they bloom"}, {"text": "- Cut back feeding and siphon leftovers so their food source disappears\n- Scrape and siphon visible hydra off the glass\n- Add fish that eat them, such as gouramis or some mollies, in tanks without fry\n- Fenbendazole is the most common treatment; it kills hydra and planaria but also kills snails, so remove snails first\n- Some products made for this purpose are shrimp safe at the right dose, but many also kill snails, so always read labels and follow them exactly\n\nAfter a treatment, vacuum dead hydra and do a 25 to 50 percent water change, since the die-off adds waste.", "heading": "Removal options"}, {"text": "In a tank of adult fish, a handful of hydra is mostly cosmetic. In a shrimp or fry tank, deal with them early before they spread.", "heading": "Do you need to act"}]$g$::jsonb where slug = $g$hydra$g$;
update public.glossary_terms set sections = $g$[{"text": "- Shrimp: dwarf shrimp like cherry and crystal shrimp, plus larger amano and ghost shrimp\n- Snails: nerite, mystery, ramshorn, Malaysian trumpet and rabbit snails\n- Crayfish and dwarf crayfish, which are messy and often eat plants and slow fish\n- Freshwater crabs, many of which need land areas and escape-proof lids\n- Clams and mussels, which filter feed and are hard to keep alive long term", "heading": "Common freshwater inverts"}, {"text": "Most inverts want stable temperature and parameters more than any exact number. Shrimp and snails need some hardness to build shells and molt, so a GH of 6 to 8 degrees and KH of 2 to 6 suits many common species, while crystal shrimp prefer softer water. Ammonia and nitrite must be at zero, and nitrate ideally under 20 ppm.\n\nThey graze biofilm and algae, but most also need supplemental foods like blanched vegetables or sinking invert foods with calcium.", "heading": "Water and diet needs"}, {"text": "Many fish see small shrimp as food, so pair them with tiny, peaceful species or give them dense plants and moss. Never use copper-based medications around inverts, and check fertilizers and treatments for warnings. Acclimate slowly, often by drip over an hour, since sudden changes can cause failed molts.", "heading": "Tankmates and safety"}, {"text": "Adding shrimp to an uncycled tank, keeping them with larger fish, and making big sudden water changes with very different water are the main causes of losses. Moderate, regular changes with matched temperature work best.", "heading": "Common mistakes"}]$g$::jsonb, faq = $g$[{"a": "Nerite and mystery snails and amano shrimp do well with most peaceful community fish. Cherry shrimp do best with small, peaceful tankmates.", "q": "What invertebrates can live with fish?"}, {"a": "Many shrimp and snails are fine at room temperature from about 68 to 78°F, but a heater keeps things stable, which they value more than any exact number.", "q": "Do aquarium invertebrates need a heater?"}, {"a": "The usual causes are an uncycled tank, copper exposure, soft water lacking minerals, or sudden swings during water changes.", "q": "Why do my shrimp and snails keep dying?"}]$g$::jsonb where slug = $g$invertebrate$g$;
update public.glossary_terms set body = $g$MTS stir the substrate, which helps prevent compacted dead spots, and they eat leftover food. Because they breed without eggs you can see, populations can explode in tanks with too much food, and many keepers count them as pests. Feeding habits decide which side of that line they land on.$g$, sections = $g$[{"text": "Malaysian trumpet snails (often shortened to MTS) spend the day buried, turning over sand and gravel as they feed. That gentle digging lets water reach the deeper layers and keeps the bottom from turning black and stagnant. At night they come up the glass to graze. They eat leftovers, biofilm and decaying plant matter, and they rarely damage healthy plants.", "heading": "Why people keep them"}, {"text": "They are hardy and adapt to a temperature range of about 70 to 82 F and a pH of 7 to 8. They need some hardness for shells; thin or pitted shells point to soft, acidic water. Adults usually reach about 0.5 to 1 inch. They give birth to live young, so a single snail can start a colony.", "heading": "Care basics"}, {"text": "Numbers follow food. A tank full of trumpet snails is a sign of overfeeding.\n\n- Cut feeding and siphon leftovers\n- Drop a blanched vegetable slice in at night and remove it in the morning with the snails on it\n- Add a snail-eating predator like assassin snails, or loaches in tanks large enough for them\n- Avoid chemical snail killers, which can cause a die-off that spikes ammonia and also harm shrimp\n\nTheir hard shell and operculum make them tougher for fish to eat than ramshorns or bladder snails.", "heading": "Controlling the population"}, {"text": "It depends on your goals. In planted tanks with sand they are often welcome; in a show tank with bare glass, hundreds of snails on the glass at night can be unwanted.", "heading": "Is it a pest"}]$g$::jsonb where slug = $g$malaysian-trumpet-snail$g$;
update public.glossary_terms set faq = $g$[{"a": "A molt is a clear, empty shell. A dead shrimp has flesh inside, often turns pink or white, and does not move.", "q": "Is my shrimp dead or did it molt?"}, {"a": "No. Shrimp eat old shells to reclaim minerals. Only remove them if they sit untouched for several days.", "q": "Should I remove shrimp molts from the tank?"}, {"a": "Failed molts usually come from mineral problems, GH that is too low, too high or swinging, or from large sudden water changes.", "q": "Why are my shrimp dying while molting?"}]$g$::jsonb where slug = $g$molting$g$;
update public.glossary_terms set sections = $g$[{"text": "Mystery snails grow to about 2 inches. One or two do well in a 10 gallon or larger tank. Keep the water at about 68 to 82 F, pH 7 to 8, and GH of 8 or more so the shell stays strong. They breathe air through a siphon tube, so leave an inch or two of space between the water and the lid, and keep the lid tight because they explore.", "heading": "Basic care"}, {"text": "They eat leftover flakes and pellets, but in a clean tank they need their own food. Offer sinking pellets, algae wafers and blanched vegetables like zucchini, spinach or cucumber a few times a week. Calcium sources such as cuttlebone or calcium-rich foods help shell growth. A starving mystery snail may start nibbling soft plants.", "heading": "Feeding"}, {"text": "Mystery snails have separate sexes. Females lay a pink, firm clutch of eggs above the waterline, often on the lid. Each clutch can hold 100 or more eggs that hatch in about 2 to 4 weeks. To prevent babies, remove the clutch and freeze it before throwing it away. To hatch them, leave the clutch in a humid spot above the water.", "heading": "Eggs and breeding"}, {"text": "- A snail floating for a day can be normal; check with a sniff test, since a dead snail smells strongly\n- Pitted or cracked shells point to soft water or low calcium\n- Avoid fin-nipping fish and puffers that pick at their tentacles\n- Never dose copper medications with snails in the tank\n\nThey live about 1 to 2 years.", "heading": "Health signs and mistakes"}]$g$::jsonb where slug = $g$mystery-snail$g$;
update public.glossary_terms set definition = $g$The nerite snail is a small algae-eating snail that lays eggs whose larvae cannot develop in freshwater, so it will not overrun an aquarium.$g$, sections = $g$[{"text": "Nerites eat green spot algae, film algae, diatoms and soft green algae that many other cleaners ignore. They don't breed in freshwater because their larvae need brackish water, so a few snails stay a few snails. Popular types include zebra, tiger, olive, horned and racing nerites, most reaching 0.5 to 1 inch.", "heading": "Why keepers love them"}, {"text": "- Temperature 72 to 80 F\n- pH 7 to 8 with moderate hardness; soft acidic water erodes their shells\n- One snail per 5 gallons is a good starting point\n- A lid, since nerites often crawl above the waterline and out\n- Supplemental algae wafers or blanched vegetables once algae runs low\n\nAdd them to a mature tank with some algae, not a brand new one.", "heading": "Care requirements"}, {"text": "Females lay small white sesame-seed eggs on hardscape, glass and wood. The eggs can't produce baby snails in freshwater, but they are hard to scrape off. A razor blade on glass works, and rocks can be scrubbed. Keeping only one or two snails or choosing a species that lays fewer eggs reduces the problem.", "heading": "About the eggs"}, {"text": "Nerites often flip over and can't right themselves, so turn them back over if you see one stuck. A snail that doesn't move for days may still be alive; check whether the trapdoor (operculum) is closed tightly before assuming it is dead. Copper medications will kill them. Most live 1 to 2 years.", "heading": "Common problems"}]$g$::jsonb, faq = $g$[{"a": "They lay eggs, but the larvae can't survive without brackish water, so the population won't grow.", "q": "Do nerite snails reproduce in freshwater?"}, {"a": "About one per 5 gallons, adjusted to how much algae is available.", "q": "How many nerite snails should I get?"}, {"a": "Nerites often rest for a day or two. If it smells or the body hangs out of the shell, it has died.", "q": "Why is my nerite snail not moving?"}]$g$::jsonb where slug = $g$nerite-snail$g$;
update public.glossary_terms set sections = $g$[{"text": "Planaria are flat, white, brown or black worms usually under about half an inch long, with an arrow or spade-shaped head and two eyespots that look cross-eyed. They glide smoothly instead of wiggling. They come out on the glass at night or after feeding. If the worm is round and wriggles, it is more likely a harmless detritus worm.", "heading": "How to identify them"}, {"text": "Planaria hunt small, slow or molting animals. They eat shrimp eggs, baby shrimp and snail eggs, and in large numbers they can stress and kill adult shrimp. They multiply quickly by splitting in two, and cutting one up only creates more.", "heading": "Why they are a problem"}, {"text": "- Cut back feeding and siphon leftover food\n- Use a planaria trap baited with a bit of meat overnight and empty it in the morning\n- Fenbendazole is commonly used against planaria and hydra, but it also kills snails, so remove snails first\n- Some products made for planaria are shrimp safe when dosed exactly as labeled, though most of them also kill snails\n- Many fish, like small gouramis and some tetras, eat planaria in tanks without shrimp\n\nAfter treatment, siphon dead worms and change 25 to 50 percent of the water, since a die-off fouls the tank.", "heading": "How to get rid of them"}, {"text": "Planaria hitch in on plants and with live food. Inspect and quarantine new plants, don't overfeed, and keep the substrate clean. A trap left in overnight every so often shows whether any remain.", "heading": "Prevention"}]$g$::jsonb, faq = $g$[{"a": "Not to healthy adult fish, but they can eat fish eggs, fry, baby shrimp and weak adult shrimp.", "q": "Are planaria harmful to fish?"}, {"a": "They arrive on plants, decor or with live food, then multiply when there is extra food.", "q": "How did planaria get in my tank?"}, {"a": "Many shrimp keepers use it successfully at standard doses, but some report shrimp losses, it kills snails and results vary, so dose carefully and watch your shrimp.", "q": "Does fenbendazole kill planaria without killing shrimp?"}]$g$::jsonb where slug = $g$planaria$g$;
update public.glossary_terms set sections = $g$[{"text": "Ramshorns reach about 0.5 to 1 inch and do fine in tanks as small as 5 gallons. They tolerate 65 to 80 F and prefer pH above 7 with some hardness; thin, pitted shells point to soft acidic water. They eat algae, biofilm, leftovers and decaying plant leaves, and rarely bother healthy plants unless starving. Their blood carries hemoglobin, which is why red and pink varieties look red.", "heading": "Care basics"}, {"text": "Each snail has both male and female parts, and any two can mate. They lay clear jelly-like clutches of 10 to 30 eggs on glass, plants and decor. Babies hatch in about 1 to 3 weeks, faster in warm water. Population size follows food supply closely, so a well-fed tank will soon have many.", "heading": "Breeding"}, {"text": "- Feed fish only what they finish in a couple of minutes\n- Scrape egg clutches off the glass\n- Trap snails overnight with a blanched vegetable slice\n- Add assassin snails, or snail-eating fish where suitable\n- Sell or trade extras with other hobbyists, since colorful ramshorns are popular\n\nSkip chemical snail killers, which harm shrimp and can cause ammonia spikes from mass die-offs.", "heading": "Keeping numbers in check"}, {"text": "The common aquarium ramshorn is a small planorbid snail. The giant ramshorn sold in some stores is a different animal, a kind of apple snail that can pass 1.5 inches and will eat plants. Ask what species you are buying if plants matter to you.", "heading": "Common confusion"}]$g$::jsonb where slug = $g$ramshorn-snail$g$;
update public.glossary_terms set sections = $g$[{"text": "Scuds are amphipods, gray to tan or greenish, about 0.1 to 0.5 inch long, with curved bodies flattened side to side. They swim on their sides in quick darting bursts and hide in moss, plant roots and leaf litter. Unlike dwarf shrimp, they don't walk upright and have no fan-shaped tail.", "heading": "How to recognize scuds"}, {"text": "They hitch rides on plants, moss and wood from other tanks or ponds, and sometimes arrive in live food cultures. Since they breed fast, a couple can become hundreds in a few months in a tank without fish.", "heading": "How they get in"}, {"text": "- Helpful: they eat detritus and leftovers, and they make excellent live food for fish\n- Neutral to bad: large colonies may graze soft plants, moss and new growth\n- Debated: some shrimp keepers report scuds eating shrimplets or weak shrimp, while others keep both together without trouble\n\nIn a fish tank, scuds rarely last long. In shrimp-only or plant-only tanks they can explode.", "heading": "Harmful or helpful"}, {"text": "The easiest control is a few small fish that eat them, but that won't work in a shrimp breeding tank where fish would also eat shrimplets. Otherwise, reduce feeding and trap them with food at night. Chemical treatments that kill scuds also kill shrimp, so avoid them in mixed tanks. Many hobbyists move valuable shrimp to a new tank instead. Check new moss carefully before adding it to a shrimp tank.", "heading": "Controlling them"}]$g$::jsonb where slug = $g$scuds$g$;
update public.glossary_terms set definition = $g$Bioload is the total amount of waste an aquarium has to process, from fish and invertebrates plus uneaten food and decaying matter.$g$, body = $g$Bioload decides how much ammonia your filter and bacteria have to handle each day. When it outgrows the tank's capacity, ammonia, nitrite and nitrate climb, fish get stressed and disease follows, so it is the key idea behind stocking, feeding and maintenance.$g$, faq = $g$[{"a": "Test for ammonia, nitrite and nitrate. Any ammonia or nitrite, or nitrate rising fast between changes, usually means the tank is over its capacity.", "q": "How do I know if my tank's bioload is too high?"}, {"a": "Yes, but very little. Snails in large numbers can add up, and large snails like mystery snails produce noticeable waste.", "q": "Do snails and shrimp add to bioload?"}, {"a": "Partly. More filtration handles more ammonia, but space, oxygen, behavior and nitrate buildup still limit how many fish a tank can hold.", "q": "Does a bigger filter let me keep more fish?"}]$g$::jsonb where slug = $g$bioload$g$;
update public.glossary_terms set sections = $g$[{"text": "Open-top tanks, warm water, strong surface agitation, dry indoor air and fans or air conditioning all speed evaporation. A typical covered 29 gallon might lose a quarter to half a gallon a week, while an open-top tank at 80 F in a dry home can lose several gallons. Only pure water evaporates; minerals, salts and pollutants stay behind.", "heading": "How fast tanks evaporate"}, {"text": "As the water level drops, everything left behind becomes more concentrated. GH, KH and total dissolved solids rise, which is a real concern for soft-water fish and sensitive shrimp. Low water can also make hang-on-back filters gurgle or run dry, and expose heaters, which can crack if they run out of water.", "heading": "Why it matters"}, {"text": "- Use a lid or glass cover; this is the single biggest fix\n- Lower the room temperature or the tank temperature if fish allow\n- Keep fans and vents from blowing across the surface\n- Avoid extra surface splashing beyond what fish need for oxygen\n\nDon't eliminate surface movement entirely, since gas exchange keeps oxygen levels healthy.", "heading": "How to reduce evaporation"}, {"text": "Top off with dechlorinated fresh water. In a soft-water or shrimp tank, use pure RO or distilled water so you restore the level without adding more minerals. Keep up regular partial water changes as well, since topping off alone never removes nitrate or excess minerals. In brackish tanks, never add salt when topping off, because the salt did not evaporate.", "heading": "Handling evaporation the right way"}]$g$::jsonb where slug = $g$evaporation$g$;
update public.glossary_terms set sections = $g$[{"text": "Cycling takes about 4 to 8 weeks, but a tank is fully mature only after several months. By then bacteria colonize every surface, biofilm coats glass and decor, plants are rooted and the tank handles daily waste with ammonia and nitrite always at 0 ppm. Numbers stay steady between water changes and pH no longer drifts much.", "heading": "What maturity looks like"}, {"text": "- Resists ammonia spikes when you add fish or overfeed slightly\n- Biofilm and microfauna provide constant grazing for shrimp, otocinclus and fry\n- Less algae trouble once plants and nutrients settle\n- Better survival for sensitive species like crystal shrimp, discus and many wild-caught fish\n\nThat is why stores and breeders often say an animal needs a mature tank.", "heading": "Why it matters"}, {"text": "Moving a used filter sponge, some media or a handful of substrate from a healthy mature tank into a new one carries a big dose of beneficial bacteria. A new tank can often be cycled in a few days to a week or two this way. Only seed from tanks without disease outbreaks, and still test water closely for the first few weeks.", "heading": "Seeding new tanks from a mature one"}, {"text": "Don't replace all filter media at once or rinse it in chlorinated tap water. Avoid deep cleaning everything on the same day. Keep up steady water changes so old-tank syndrome, where nitrate builds and pH slowly falls, does not creep in over the years. Replace only part of the media at a time when it truly wears out.", "heading": "Keeping a tank mature"}]$g$::jsonb where slug = $g$mature-tank$g$;
update public.glossary_terms set sections = $g$[{"text": "- Adult size, not store size\n- Minimum tank length for active swimmers\n- Water needs: temperature, pH and hardness that all species share\n- Temperament: peaceful, semi-aggressive, fin-nippers or territorial\n- Swimming level: top, middle or bottom, to use the whole tank\n- Group size: schooling fish usually need 6 or more\n- Waste output: goldfish and large cichlids need far more filtration", "heading": "What to consider"}, {"text": "The old one inch of fish per gallon rule is a rough guide at best. It treats one 12 inch adult oscar the same as eight 1.5 inch neon tetras, which is badly wrong. Body mass, activity level and territory matter more than length. Use it only as a sanity check for small, slim community fish.", "heading": "Why simple rules fall short"}, {"text": "Add fish in small groups over weeks, giving bacteria time to catch up. Start with hardy species, often a school of peaceful midwater fish, then add bottom dwellers, and add centerpiece or more territorial fish last so they don't claim the whole tank early. Test ammonia and nitrite a few days after each addition.", "heading": "Stocking in order"}, {"text": "Mixing fish that need very different temperatures, buying single schooling fish, choosing fish based only on color, and putting fin-nippers like tiger barbs with long-finned fish like bettas are the classic errors. Ask about each fish's adult needs before buying. Then buy from a store or breeder that quarantines its stock, and quarantine new fish yourself for 2 to 4 weeks when you can.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$stocking$g$;
update public.glossary_terms set faq = $g$[{"a": "For most community tanks, yes. Water quality is more stable and fish are less stressed.", "q": "Is it better to understock a fish tank?"}, {"a": "Yes, if schooling fish are kept in tiny groups or shy fish lack cover. Group size matters more than total numbers.", "q": "Can a tank be too understocked?"}, {"a": "Usually, since less waste means fewer nutrients, though lighting also plays a major role.", "q": "Does understocking reduce algae?"}]$g$::jsonb where slug = $g$understocking$g$;
update public.glossary_terms set sections = $g$[{"text": "Most tanks do well with a partial water change of 20 to 30 percent once a week. Heavily stocked tanks or messy fish may need 40 to 50 percent weekly, or two changes a week. Lightly stocked planted tanks can sometimes stretch to every two weeks. Let your nitrate readings guide you: aim to keep nitrate under about 20 to 40 ppm.", "heading": "How much and how often"}, {"text": "- Unplug heaters and filters if the water level will drop below them\n- Siphon water out with a gravel vacuum, cleaning a section of substrate as you go\n- Wipe glass and rinse filter sponges in the removed tank water if needed\n- Prepare new water at about the same temperature, within 2 F\n- If you fill straight from the tap, add dechlorinator for the full tank volume, not just the new water\n- Refill slowly, then plug equipment back in", "heading": "Step by step"}, {"text": "Changing all the water at once swings temperature, pH and hardness, which shocks fish and can trigger failed molts in shrimp. A partial change keeps those swings small. Fish in tanks that have gone months without changes are adjusted to poor water, so restore them with several smaller changes, about 10 to 20 percent every day or two, rather than one huge one.", "heading": "Why partial and not all"}, {"text": "Forgetting dechlorinator, refilling with water much colder or warmer than the tank, rinsing filter media under tap water, and replacing filter cartridges at the same time as a big change all cause problems. Keep a dedicated bucket that never touches soap.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$water-change$g$;
update public.glossary_terms set seo_title = $g$Beneficial Bacteria in Aquariums: What They Do and How to Grow$g$, sections = $g$[{"text": "Fish produce ammonia through their gills and waste, and uneaten food rots into more of it. Ammonia burns gills even at low levels. Beneficial bacteria, also called nitrifying bacteria, are the colonies that eat that ammonia and turn it into nitrite, then turn the nitrite into nitrate. Nitrate is far less toxic and leaves the tank when you do water changes.\n\nThis two-step process is the nitrogen cycle, and the lack of it is the single biggest reason a new tank kills fish and an established one doesn't.", "heading": "What beneficial bacteria actually do"}, {"text": "Almost none of these bacteria float in the water. They grow as a film on surfaces with steady water flow: filter sponges and ceramic media, gravel, rocks, driftwood and plant leaves. That is why a used filter sponge from a healthy tank can jump-start a new one, and why a bottle of water from an old tank does very little.", "heading": "Where they live"}, {"text": "- Give them food: ammonia from fish food, a pure ammonia source, or a few hardy fish added slowly.\n- Give them surface area: a filter with sponge or porous media and good flow.\n- Be patient: a colony usually takes 4 to 8 weeks to handle a full load. Bottled bacteria and seeded media can cut that down.\n- Test the water: the tank is cycled when ammonia and nitrite both read 0 and nitrate is showing up.", "heading": "How to grow a colony"}, {"text": "- Rinsing filter media under chlorinated tap water. Rinse it in old tank water instead.\n- Replacing all the filter media at once.\n- Some medications, especially antibiotics.\n- Letting the filter sit off for hours, which starves the colony of oxygen.\n- Untreated tap water with chlorine or chloramine.", "heading": "What kills them"}]$g$::jsonb where slug = $g$beneficial-bacteria$g$;
update public.glossary_terms set faq = $g$[{"a": "In a new tank it usually takes 4 to 8 weeks. Seeding with media from a healthy tank can cut that to a few days or a week or two.", "q": "How long does it take to establish biological filtration?"}, {"a": "Not strictly. A plain sponge holds plenty of bacteria for most tanks, though ceramic or porous media adds extra capacity in a small space.", "q": "Do I need special bio media?"}, {"a": "No. Very few of the bacteria float in the water, so normal water changes leave the colony in place as long as you dechlorinate the new water.", "q": "Does a water change remove the good bacteria?"}]$g$::jsonb where slug = $g$biological-filtration$g$;
update public.glossary_terms set sections = $g$[{"text": "- Activated carbon: removes tannins, odors and many medications. The most common choice.\n- Ion exchange resins: pull out organics or nitrate, depending on the resin. Some can be recharged.\n- Phosphate removers: help in tanks with stubborn phosphate and algae.\n- Zeolite: absorbs ammonia for a short time, useful in emergencies but it fills up fast.", "heading": "Common types"}, {"text": "Run carbon after a course of medication to strip what is left, after you add new driftwood if you dislike the brown tint, or if the tank smells off even with good maintenance.\n\nMany healthy community tanks run without any chemical media at all. Regular weekly partial water changes do most of the same job by diluting what builds up.", "heading": "When it helps"}, {"text": "Place chemical media after the mechanical stage so debris does not clog it. Rinse carbon before use to remove dust.\n\nCarbon stops working once its pores fill, often within 2 to 4 weeks in a busy tank. After that it just becomes extra surface for bacteria, so replace it if you are relying on it for a purpose.", "heading": "How to use it properly"}, {"text": "Take carbon out before medicating, or it will absorb the treatment and leave your fish unprotected. In planted tanks, carbon may also remove some liquid fertilizer, so many plant keepers skip it. Never use zeolite in tanks that get aquarium salt, since salt makes it release the ammonia it was holding.", "heading": "Mistakes to avoid"}]$g$::jsonb where slug = $g$chemical-filtration$g$;
update public.glossary_terms set definition = $g$Cycling, short for cycling a tank, is growing enough beneficial bacteria in a new aquarium to convert fish waste safely, ideally before fish are added.$g$, sections = $g$[{"text": "First, an ammonia source starts the process, either bottled ammonia, fish food or the fish themselves. Bacteria that eat ammonia grow and turn it into nitrite, so ammonia falls and nitrite climbs. A second group of bacteria then turns nitrite into nitrate.\n\nThe tank is cycled when it handles a full day's ammonia with 0 ppm ammonia and 0 ppm nitrite showing on a test, and nitrate rising.", "heading": "What happens during a cycle"}, {"text": "- Set up the tank with filter and heater running and dechlorinated water.\n- Choose a method: fishless cycling with an ammonia source is safest, fish-in cycling is possible with daily care.\n- Test ammonia, nitrite and nitrate every couple of days with a liquid test kit.\n- Optionally add bottled bacteria or seeded media to speed things up.\n- When readings hit 0, 0 and some nitrate, do a large water change and add fish slowly.", "heading": "How to cycle a tank"}, {"text": "Expect 4 to 8 weeks for a fishless cycle from scratch. A warm tank around 78 to 82 F with pH above 7 cycles faster. Seeding from an established tank can cut it to a few days or a week or two.", "heading": "How long it takes"}, {"text": "Do not deep clean the filter mid-cycle, and in a fishless cycle keep adding ammonia after the tank is cycled until fish go in, or the bacteria starve. Very high nitrite can stall the second stage, so a water change helps if nitrite stays off the chart for a week or more. Adding a full stock of fish at once can overwhelm even a cycled tank.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$cycling$g$;
update public.glossary_terms set sections = $g$[{"text": "The bacteria that do this live where oxygen is very low or absent. With no oxygen to breathe, they use the oxygen in nitrate instead and release nitrogen gas. They also need a carbon food source, which comes from fish waste and organic matter or, in dedicated reactors, from added carbon.\n\nThese zones form deep inside porous rock, thick dense media and sand beds more than a few inches deep.", "heading": "How it works"}, {"text": "- Deep sand beds, mostly in saltwater systems.\n- Very porous bio media with slow flow through its core.\n- Dedicated denitrifying reactors and sulfur reactors, which are more common in reef keeping.\n- Thick layers of undisturbed substrate in planted tanks.", "heading": "Where you see it in home tanks"}, {"text": "In a typical freshwater tank the effect is small and hard to measure. If you see nitrate climbing, the real fixes are feeding less, adding plants, and doing larger or more frequent water changes.\n\nDeep anaerobic substrate is debated in freshwater. If it is disturbed, pockets can release hydrogen sulfide, which smells like rotten eggs and is toxic to fish. Burrowing snails like Malaysian trumpet snails help by stirring sand gently.", "heading": "Limits and risks"}, {"text": "Large, heavily stocked tanks such as cichlid or goldfish setups sometimes use denitrifying media or reactors to cut water change load. For most community tanks, treat any denitrification as a small bonus, not a plan. Plants remain the more reliable natural way to pull nitrate out between water changes.", "heading": "When to bother with it"}]$g$::jsonb where slug = $g$denitrification$g$;
update public.glossary_terms set sections = $g$[{"text": "- Coarse sponge: mechanical filtration that catches large debris and holds lots of bacteria.\n- Fine floss or pads: polish the water by trapping tiny particles. Clogs fast.\n- Ceramic rings, porous stone, bio balls: biological media with large surface area for bacteria.\n- Activated carbon and resins: chemical media for tannins, odors and medication.", "heading": "Types of media"}, {"text": "A common order is coarse to fine to biological, then chemical. Coarse sponge first keeps fine floss from clogging in a day, and keeping debris off the bio media protects the bacteria living there.\n\nIf your filter came with one all-in-one cartridge, you can often replace it with a sponge and a bag of ceramic media for better results and less waste. In small hang-on-back filters, a coarse sponge plus a pouch of ceramic rings is a simple, effective setup.", "heading": "The right order"}, {"text": "Rinse sponges and bio media in a bucket of removed tank water every 2 to 6 weeks, just enough to clear clogs. Chlorine or chloramine in tap water can kill the bacteria.\n\nSponges and ceramic media last for years. Floss is cheap and can be replaced when it is clogged. Never replace everything at once; change no more than a third of the media at a time.", "heading": "Cleaning and replacing"}, {"text": "Throwing out the cartridge every month as packaging suggests is the classic one, since it throws away bacteria too. Packing media so tightly that water bypasses it is another. Leaving carbon in while medicating is a third. Finally, using only fine floss in a heavily stocked tank leads to clogging and poor flow within days.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$filter-media$g$;
update public.glossary_terms set sections = $g$[{"text": "- Keep the stock light: a few hardy fish, not a full tank.\n- Feed small amounts once a day or every other day.\n- Test ammonia and nitrite daily with a liquid kit.\n- Change 25 to 50 percent of the water whenever ammonia plus nitrite reaches about 0.5 ppm.\n- Use a dechlorinator that also binds ammonia and nitrite temporarily.\n- Keep the temperature steady and toward the warmer end of what your fish are comfortable with, since the bacteria grow faster in warmth.", "heading": "How to do it safely"}, {"text": "Bottled bacteria products can shorten the process. A handful of filter media or a squeezed sponge from a healthy tank works even better. Live plants help too, since they take up ammonia directly.\n\nExpect the cycle to take 4 to 8 weeks. It may feel slower than fishless cycling because frequent water changes keep ammonia low, which is the point. Avoid adding shrimp or snails until the cycle is finished, since invertebrates are very sensitive to ammonia and nitrite.", "heading": "Speeding it up"}, {"text": "Gasping at the surface, red or inflamed gills, lethargy, clamped fins and refusing food all suggest ammonia or nitrite stress. Test right away and do a water change if readings are up.", "heading": "Signs your fish are struggling"}, {"text": "The tank is cycled when ammonia and nitrite stay at 0 ppm for about a week without water changes and nitrate is rising. Add new fish a few at a time over the next weeks so the bacteria can keep up. Keep testing weekly after that, since a newly cycled tank can still slip if you overfeed or add too many fish at once.", "heading": "When it is done"}]$g$::jsonb where slug = $g$fish-in-cycling$g$;
update public.glossary_terms set sections = $g$[{"text": "New tank syndrome is the wave of sick and dying fish in an aquarium that hasn't built up its beneficial bacteria yet. Without those bacteria, ammonia and then nitrite climb to toxic levels within days of adding fish. The tank looks fine, and the water is often crystal clear, but it is poisoning the fish.", "heading": "What new tank syndrome is"}, {"text": "- Fish gasping at the surface or hanging near the filter\n- Red or inflamed gills\n- Lethargy, clamped fins, not eating\n- Cloudy water from a bacterial bloom in the first week or two\n- Test kit showing ammonia or nitrite above 0", "heading": "Signs"}, {"text": "- Cycle the tank before adding fish (fishless cycling), feeding it an ammonia source until it can turn a dose into 0 ppm ammonia and 0 ppm nitrite within about a day.\n- Seed the filter with media or sponge from a healthy tank.\n- Add fish a few at a time over weeks, not all at once.\n- Feed lightly and test every few days for the first two months.", "heading": "How to prevent it"}, {"text": "Test daily. Whenever ammonia plus nitrite climbs toward about 0.5 ppm, do a 30 to 50 percent water change with dechlorinated water, feed lightly and use a conditioner that detoxifies ammonia and nitrite. Don't clean or replace the filter media. It usually settles in 4 to 8 weeks.", "heading": "If fish are already in the tank"}]$g$::jsonb, faq = $g$[{"a": "Until the tank finishes cycling, usually 4 to 8 weeks.", "q": "How long does new tank syndrome last?"}, {"a": "Cloudy white water in a new tank is usually a harmless bacterial bloom, but it can mean the tank isn't fully cycled yet. Test for ammonia and nitrite.", "q": "Does cloudy water mean new tank syndrome?"}, {"a": "It's the most common cause of new tank syndrome. Cycle first, or use fully seeded media and add only a few hardy fish.", "q": "Can I add fish the same day I set up a tank?"}]$g$::jsonb where slug = $g$new-tank-syndrome$g$;
update public.glossary_terms set sections = $g$[{"text": "- Ammonia: released by fish gills, waste, uneaten food and decay. Harmful even at low readings over time, and more toxic at higher pH and temperature.\n- Nitrite: produced when the first group of bacteria eats ammonia. Also toxic, it blocks fish blood from carrying oxygen.\n- Nitrate: produced when a second group eats nitrite. Much safer, but it builds up and should be kept under about 20 to 40 ppm.", "heading": "The three stages"}, {"text": "The bacteria live on surfaces, mostly inside the filter, but also on gravel, decor and plants. They need oxygen and steady flow, which is why the filter should run all the time.\n\nIn a new tank these bacteria do not exist yet. Growing them is called cycling and takes about 4 to 8 weeks. Fishless cycling with a bottled ammonia source is the safest way to grow them before fish arrive.", "heading": "Where it happens"}, {"text": "The cycle stops at nitrate in most aquariums. You remove it with regular water changes of 25 to 50 percent a week. Live plants and algae also use some, and a small amount is turned into nitrogen gas in low-oxygen spots.", "heading": "How nitrate leaves the tank"}, {"text": "Feed only what fish eat in a minute or two, add fish gradually, and clean filter media in removed tank water. Test ammonia, nitrite and nitrate regularly. In an established tank, ammonia and nitrite should always read 0 ppm. A liquid test kit is more accurate than paper strips for these readings. If ammonia or nitrite ever shows up, do a water change and look for the cause, such as overfeeding, a dead fish or a recently cleaned filter.", "heading": "Keeping the cycle healthy"}]$g$::jsonb where slug = $g$nitrogen-cycle$g$;
update public.glossary_terms set body = $g$It is one of the most popular beginner plants because it tolerates low to moderate light and grows big and lush. It is a heavy root feeder that can reach 16 to 20 inches tall, so it suits larger tanks, 20 gallons at the very least and ideally a taller tank of 30 gallons or more.$g$, faq = $g$[{"a": "It does best with them. It feeds mainly through its roots, so plain gravel needs root tabs every few months.", "q": "Does Amazon sword need root tabs?"}, {"a": "Usually because it was grown out of water and is switching to underwater leaves. Keep the crown healthy and new growth will follow.", "q": "Why is my Amazon sword melting?"}, {"a": "Often 16 to 20 inches tall and wide in good conditions, so it is best in larger, taller tanks, ideally 30 gallons or more.", "q": "How big does an Amazon sword get?"}]$g$::jsonb where slug = $g$amazon-sword$g$;
update public.glossary_terms set sections = $g$[{"text": "- Light: low to moderate. Strong light leads to algae on the slow leaves.\n- Temperature: 72 to 82°F.\n- pH: about 6.0 to 7.5.\n- Feeding: takes nutrients from the water, so a light liquid fertilizer helps.\n- Growth: slow, often one new leaf every few weeks.\n\nPopular kinds include Anubias barteri and its varieties, such as coffeefolia with its puckered leaves, the compact nana and the tiny nana petite.", "heading": "Care basics"}, {"text": "Tie the rhizome to wood or rock with cotton thread or fishing line, or use a dab of gel superglue. Within a few weeks roots grip the surface and the tie can be removed.\n\nYou can also wedge it between rocks, or set the roots in sand with the rhizome sitting on top.", "heading": "How to plant it"}, {"text": "Cut the rhizome with a clean blade into pieces that each have at least 3 or 4 leaves. Each piece grows into a new plant. Side shoots that form naturally can be split off the same way.", "heading": "Propagation"}, {"text": "Rhizome rot shows as a soft, mushy brown section with leaves falling off. Cut away the rotten part and keep the rhizome uncovered.\n\nGreen spot algae often settles on old leaves because they last so long. Shade the plant, shorten the light period, or wipe leaves gently. Nerite snails graze it slowly and can help. Yellowing leaves usually point to low nitrogen or iron. Plant-eating fish like silver dollars usually leave it alone, which makes it a good choice for tough tanks.", "heading": "Common problems"}]$g$::jsonb where slug = $g$anubias$g$;
update public.glossary_terms set sections = $g$[{"text": "Black beard algae, or BBA, is a red algae that grows as dark gray to black tufts on slow-growing leaves, wood, rocks, the filter intake and tank edges. It clings hard and doesn't wipe off like green algae, which is why it frustrates planted-tank keepers.", "heading": "What black beard algae is"}, {"text": "- Unstable CO2, especially CO2 that swings up and down during the day\n- Low-flow dead spots\n- Excess organic waste and old, uncleaned filters\n- Slow-growing plants like anubias and java fern that give it time to settle", "heading": "What causes it"}, {"text": "- Fix the cause first: steady CO2, better flow and regular water changes.\n- Trim and throw out badly covered leaves.\n- Spot treat with liquid carbon (glutaraldehyde) or diluted hydrogen peroxide using a syringe with the filter off for a few minutes, following the product's dosing guidance. Go easy, since overdosing either one can harm shrimp, snails and sensitive plants. Treated BBA turns pink or white, then gets eaten or dies off.\n- Scrub hardscape outside the tank, or soak it in a diluted peroxide solution before rinsing.\n- Young Siamese algae eaters and some shrimp will graze it once it's weakened.", "heading": "How to get rid of it"}]$g$::jsonb where slug = $g$black-beard-algae$g$;
update public.glossary_terms set sections = $g$[{"text": "Pest cladophora grows as stiff, branched dark green threads that feel rough, almost like wet steel wool, unlike slimy hair algae. It often tangles into moss and around stem plants and rarely floats free.\n\nMarimo moss balls are round, dense, velvety green spheres that grow only a few millimeters a year. They are now classified as Aegagropila linnaei but are still widely sold under the old Cladophora name.", "heading": "How to identify it"}, {"text": "Pest cladophora almost always hitchhikes on new plants or moss. Inspect and rinse new plants, and quarantine them for a week or two in a separate container if possible.", "heading": "How it gets in"}, {"text": "- Pull out as much as possible by hand, winding it around a toothbrush.\n- Remove badly infested moss or plant portions entirely.\n- Spot treat remaining patches with liquid carbon or hydrogen peroxide using a syringe with the filter off for a few minutes. Overdosing can harm shrimp, snails and delicate plants like Vallisneria.\n- Keep nutrients balanced and lights at 6 to 8 hours to slow regrowth.\n\nFew animals eat it, though some keepers report amano shrimp and certain fish picking at it.", "heading": "How to control it"}, {"text": "Keep them in cool water under 78°F with low light, rotate them now and then, and squeeze them out in tank water every few weeks. White or pale patches usually mean too much light; brown patches often point to too little light, trapped debris or water that is too warm. Buy from trusted sources; in 2021 some shipments carried invasive zebra mussels.", "heading": "Caring for moss balls"}]$g$::jsonb where slug = $g$cladophora$g$;
update public.glossary_terms set sections = $g$[{"text": "- A pressurized cylinder stores the gas.\n- A regulator lowers the pressure, and a needle valve sets the bubble rate.\n- A solenoid valve on a timer turns gas on and off.\n- A bubble counter shows the flow rate.\n- A diffuser or reactor dissolves the gas into the water.\n- A drop checker shows the level by color.\n\nDIY yeast or citric acid kits exist for small tanks, but they are harder to control.", "heading": "How a system works"}, {"text": "Most planted tanks aim for about 20 to 30 ppm CO2. A drop checker filled with 4 dKH reference solution turns lime green at roughly that level, blue when too low and yellow when too high.\n\nStart with a low bubble rate and raise it slowly over a week or two while watching fish. A pH drop of about 1.0 from fully degassed water to the peak of the CO2 period is a common target.", "heading": "Safe levels and dialing it in"}, {"text": "Turn CO2 on 1 to 2 hours before the lights so levels are up when plants start working, and off about an hour before lights out. Plants do not use CO2 in the dark, and running it overnight is a common cause of fish losses in CO2 tanks.", "heading": "Timing"}, {"text": "Fish gasping at the surface, breathing hard or lying still mean too much CO2. Turn it off, increase surface agitation and do a water change. Never adjust the needle valve and walk away; check fish for the next few hours. Shrimp are especially sensitive.", "heading": "Warning signs and mistakes"}]$g$::jsonb where slug = $g$co2-injection$g$;
update public.glossary_terms set sections = $g$[{"text": "- Slimy sheets that peel off in one piece, unlike stringy or fuzzy algae.\n- Blue-green, dark green, or sometimes red to purple color.\n- A strong earthy, musty smell when disturbed.\n- Often starts on the substrate against the front glass, where light hits and flow is weak.\n- Bubbles trapped under the film in the afternoon.", "heading": "How to identify it"}, {"text": "Low flow and dead spots are the most common factor. Excess organic waste from overfeeding and infrequent cleaning help it along. In planted tanks, very low nitrate with plenty of phosphate can favor it, which is why it sometimes shows up in tanks that seem clean. Direct sunlight on the tank also feeds it.", "heading": "What causes it"}, {"text": "- Siphon out as much as you can and do a 30 to 50 percent water change.\n- Improve circulation, especially along the bottom.\n- Do a blackout: cover the tank fully for 3 to 4 days with no light, keeping filter and aeration running, then do another water change.\n- In planted tanks, check that nitrate is not near zero.\n\nSome keepers use the antibiotic erythromycin as a last resort. It works well on cyanobacteria but should be used carefully and only as directed, and it is not allowed for sale in every area. Antibiotics can also set back the filter bacteria, so test ammonia and nitrite during and after treatment. Spot treating with hydrogen peroxide is another option, but it can harm shrimp, snails and fish at high doses.", "heading": "How to get rid of it"}, {"text": "Keep up weekly water changes, feed less, vacuum the substrate surface, and keep flow strong enough that nothing is stagnant. Return light to 6 to 8 hours after a blackout.", "heading": "Preventing a comeback"}]$g$::jsonb where slug = $g$cyanobacteria$g$;
update public.glossary_terms set sections = $g$[{"text": "Diatoms form a soft brown or golden film that wipes off easily with a finger or sponge. They appear on glass, sand, rocks and slow-growing leaves. Unlike black beard or green spot algae, they do not cling hard or form tufts.", "heading": "How to identify them"}, {"text": "New tanks have spare nutrients and silicates, which diatoms use to build their shells. Silicate comes from tap water, some sand and new substrate. Low light can also favor diatoms over green algae. As plants grow and the biological balance settles, diatoms lose their edge.", "heading": "Why they appear"}, {"text": "- Wipe glass with an algae pad and siphon brown patches off the substrate during water changes.\n- Keep up weekly water changes of 25 to 50 percent.\n- Add nerite snails, which eat diatoms eagerly and will not overrun the tank, since their eggs do not hatch in freshwater.\n- Otocinclus catfish love diatoms but should only go into a stable, cycled tank, and need extra food once the diatoms are gone.\n- Use RO water or silicate-removing media only if diatoms keep coming back in an older tank.\n\nScrubbing the glass every few days keeps the tank looking clean while you wait for diatoms to fade on their own.", "heading": "How to get rid of them"}, {"text": "In a tank older than about 3 months, persistent diatoms may point to high silicate in the source water or very low light. Test or treat the source water rather than adding more algae eaters.", "heading": "When to be concerned"}]$g$::jsonb where slug = $g$diatoms$g$;
update public.glossary_terms set body = $g$Beyond its looks, driftwood gives fish cover and territory, provides grazing for shrimp and plecos, and slowly releases tannins that slightly lower pH and tint the water amber. Some plecos, such as Panaque and Panaqolus, rasp on wood and should always have it in the tank. Most pieces need some preparation before they will sink.$g$ where slug = $g$driftwood$g$;
update public.glossary_terms set body = $g$Most carpeting plants grow faster out of water, where they get carbon straight from the air. This lets them root firmly and spread before algae can take hold, and it stops tiny plugs from floating away, and it helps carpets get established even in tanks without injected CO2.$g$ where slug = $g$dry-start-method$g$;
update public.glossary_terms set sections = $g$[{"text": "- Absorbs ammonia and nitrate quickly, helping water quality.\n- Shades the tank, which helps hold back algae and suits fish that like dim light.\n- Gives fry, bettas and gouramis cover near the surface.\n- Goldfish, some cichlids and silver dollars eat it as a green snack.", "heading": "Benefits"}, {"text": "Duckweed almost always hitchhikes on new plants, in bags of fish or on nets used in an infested tank. A single leaf can turn into a full surface layer within a few weeks in a well-fed, well-lit tank. Rinsing new plants and inspecting them closely, or keeping them in a separate container for a few days, catches most stray leaves.", "heading": "How it gets in"}, {"text": "Scoop it out with a fine net several times a week; a cup or open-ended container can corral it first. Removing it completely takes persistence, since any leaf left behind regrows. Turning off the filter while netting helps it clump.\n\nA floating ring or tube can confine it to one area. Lower surface flow and higher light make it grow faster, so stronger surface agitation helps slow it. Avoid herbicides, which harm other plants and can crash oxygen.", "heading": "How to control or remove it"}, {"text": "A thick mat blocks light to plants below and slows gas exchange, which can lower oxygen. It can also clog filter intakes and skimmers. Check new plants and rinse them before adding them to keep it out of tanks where you do not want it.", "heading": "Problems to watch for"}]$g$::jsonb, faq = $g$[{"a": "It can be. It lowers nitrate and shades out algae, but it spreads fast and needs regular thinning.", "q": "Is duckweed good for an aquarium?"}, {"a": "Net it out often and thoroughly until no leaves remain. Even one leaf can restart it, so check for weeks afterward.", "q": "How do I get rid of duckweed permanently?"}, {"a": "Yes. Goldfish, silver dollars, some cichlids and other plant-eating fish eat it readily.", "q": "Do fish eat duckweed?"}]$g$::jsonb where slug = $g$duckweed$g$;
update public.glossary_terms set sections = $g$[{"text": "- Anubias: tough dark leaves, very low light needs.\n- Java fern: long leaves, often grows little plantlets on its leaves.\n- Bucephalandra: small, colorful leaves, slow growing.\n- Mosses like Java moss and Christmas moss: cover wood and rock.\n- Bolbitis: a fern that likes good flow.", "heading": "Common epiphytes"}, {"text": "Tie the rhizome or moss to wood or rock with cotton thread, which dissolves in a few weeks, or fishing line. Gel superglue also works well and is safe once cured; a small dab on the hardscape holds the plant in place underwater.\n\nYou can also wedge plants into gaps between rocks or wood. Within a few weeks roots grip the surface on their own.", "heading": "How to attach them"}, {"text": "Keep the rhizome above the substrate at all times; burying it causes rot. Feed with a light liquid fertilizer since these plants feed from the water. Moderate flow helps bring nutrients and keeps debris off their leaves.\n\nPropagate by cutting the rhizome into pieces with several leaves each, or by collecting the baby plants Java fern grows on its leaves. Many epiphytes also grow well out of water in a humid tank, which is handy for a dry start or a paludarium.", "heading": "Care tips"}, {"text": "Slow leaves can collect algae, so keep light moderate and the light period around 6 to 8 hours. Java fern can develop black or brown patches from low nutrients, often potassium. Raised brown dots in neat rows on the underside of leaves are spores, which are normal. Moss can trap debris and needs a gentle rinse during maintenance.", "heading": "Common problems"}]$g$::jsonb where slug = $g$epiphyte$g$;
update public.glossary_terms set sections = $g$[{"text": "- Duckweed: tiny, very fast, and almost impossible to remove once established\n- Salvinia: small fuzzy leaves, easy to thin by hand\n- Amazon frogbit: round leaves with long, feathery roots\n- Red root floater: turns red under strong light and low nitrate\n- Water lettuce: large rosettes, best for open-top or big tanks\n- Water sprite: can float or be planted", "heading": "Popular choices"}, {"text": "Most floaters need little more than light and a still surface. Keep the water level a few inches below a lid or light so leaves don't scorch or stay soggy from condensation. Strong filter outflow pushes them underwater and rots the leaves, so aim the return along the glass or use a floating ring made from airline tubing to corral them. They feed from the water column, so in very clean, lightly stocked tanks a small dose of liquid fertilizer keeps them green.", "heading": "Care and light"}, {"text": "Floaters can double in a week or two. Scoop out a third to a half whenever they cover more than about half the surface, because a full mat shades the plants below and can reduce gas exchange at the surface. Every handful you remove takes the nutrients it absorbed out of the tank with it, which is part of why they work so well against algae.", "heading": "Keeping them under control"}, {"text": "Adding duckweed by accident is the classic one: it hitches a ride on store plants and spreads to every tank you own. Rinse new plants and pick off stray floaters. Also avoid floaters with goldfish, silver dollars or large cichlids unless you want them eaten, and don't let a thick mat starve a carpet plant of light.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$floating-plant$g$;
update public.glossary_terms set sections = $g$[{"text": "Green water is caused by microscopic suspended algae, often Chlorella or Euglena types, multiplying in the water itself. Blooms usually follow a combination of excess light and excess nutrients: a tank near a sunny window, lights left on 10 or more hours, overfeeding, or an ammonia spike from a new tank or a big disturbance like a deep substrate clean.", "heading": "Why it happens"}, {"text": "- UV sterilizer: the most reliable fix, often clearing water in 3 to 7 days\n- Blackout: turn off the lights and cover the tank completely for 3 to 4 days, then do a large water change\n- Diatom or very fine micron filtration catches the cells\n- Cut feeding and photoperiod while you treat\n\nWater changes alone rarely work because the algae regrows from what remains within a day or two.", "heading": "How to clear it"}, {"text": "Fish and most plants handle a few dark days well. Add an air stone, since algae and plants consume oxygen in the dark and a dense bloom dying off can drop oxygen quickly. Feed lightly, keep the tank covered, and keep peeking to a minimum, since light lets the bloom recover. Expect some leaf loss on demanding plants.", "heading": "Care during a blackout"}, {"text": "Keep the tank out of direct sunlight, run lights 6 to 8 hours on a timer, and feed only what fish finish in a minute or two. Fast-growing stem and floating plants starve suspended algae of nutrients. Avoid algaecides: they kill the bloom all at once, which can crash oxygen and harm shrimp and snails.", "heading": "Preventing it"}]$g$::jsonb where slug = $g$green-water$g$;
update public.glossary_terms set sections = $g$[{"text": "- Macronutrients: nitrogen (as nitrate), phosphorus (as phosphate) and potassium\n- Secondary nutrients such as magnesium, calcium and sulfur\n- Micronutrients: iron, manganese, boron, zinc and other trace elements\n- All-in-one products contain both, while some keepers dose them separately or mix their own dry salts\n\nPotassium deficiency shows as pinholes in older leaves; iron deficiency shows as pale or yellow new growth.", "heading": "What's in it"}, {"text": "Start with half the label dose in a low-tech tank and adjust from there. High-tech tanks with CO2 usually need the full dose, sometimes daily. Dose after your weekly water change and then on a set schedule, since a steady supply works better than occasional big doses. Many keepers aim for roughly 10 to 20 ppm nitrate and 1 to 2 ppm phosphate in planted tanks.", "heading": "How to dose"}, {"text": "Fertilizers made for aquariums are safe at the recommended dose. Overdosing can harm shrimp and snails, and some products contain copper as a trace element. It is usually a tiny amount, but shrimp keepers should dose carefully and choose products labeled shrimp safe or very low in copper. Never use houseplant or garden fertilizer, which can contain ammonia-based nitrogen at levels that harm fish.", "heading": "Safety with fish and shrimp"}, {"text": "Dosing heavily under weak light, which feeds algae instead of plants, is the most common one. Others are using only liquid fertilizer for heavy root feeders like swords and crypts, which also need root tabs, and changing several things at once so you can't tell what helped.", "heading": "Common mistakes"}]$g$::jsonb, faq = $g$[{"a": "Low-tech tanks often do well with one or two doses a week. High-tech tanks with CO2 may need dosing three times a week or daily.", "q": "How often should I add liquid fertilizer to my aquarium?"}, {"a": "Most aquarium fertilizers are shrimp safe at normal doses. Start low, avoid overdosing, and choose products labeled shrimp safe or very low in copper.", "q": "Is liquid fertilizer safe for shrimp?"}, {"a": "Only when nutrients outpace what plants can use, usually from too much fertilizer under weak light. Balanced dosing with healthy plants actually helps prevent algae.", "q": "Does liquid fertilizer cause algae?"}]$g$::jsonb where slug = $g$liquid-fertilizer$g$;
update public.glossary_terms set definition = $g$Melt is when an aquarium plant, usually a newly planted one, suddenly loses leaves, which turn soft, translucent and rot away as the plant adjusts to new conditions.$g$, sections = $g$[{"text": "Most aquarium plants are grown emersed at farms, with leaves above water. Once submerged, the plant drops those air-grown leaves and grows new ones shaped for underwater life. Sudden changes in light, temperature, CO2 or water chemistry can also trigger melt in plants that were already submersed. Cryptocoryne are famous for it, but many stem and carpet plants melt too.", "heading": "Why plants melt"}, {"text": "- Leaves turning see-through, mushy or brown, often within a week of planting\n- Whole leaves breaking off at the base\n- Healthy-looking roots or rhizome even as leaves die\n- New, often different-shaped leaves appearing within a few weeks", "heading": "Signs to watch for"}, {"text": "Remove melting leaves promptly so they don't rot and add ammonia to the tank. Leave the roots or rhizome in place, since a crypt that looks completely dead often regrows from the roots in 2 to 6 weeks. Keep conditions stable rather than moving the plant or changing lights. Root tabs near crypts and swords help them rebuild. Avoid dosing extra fertilizer to save a melting plant, since rotting leaves plus extra nutrients is a classic recipe for an algae bloom.", "heading": "How to handle it"}, {"text": "Tissue culture plants, sold in small cups of sterile gel, often adapt faster and tend to melt less. Plant into a cycled tank with stable parameters, keep CO2 and lighting consistent, and avoid moving plants around once placed. A few weeks of patience is usually all it takes.", "heading": "Reducing melt"}]$g$::jsonb where slug = $g$melt$g$;
update public.glossary_terms set faq = $g$[{"a": "Japanese aquascaper and photographer Takashi Amano developed it from the 1980s, and his books and contests spread it worldwide in the 1990s.", "q": "Who invented the Nature Aquarium style?"}, {"a": "Small schooling fish like tetras and rasboras are classic choices, often with Amano shrimp and Otocinclus for algae control.", "q": "What fish suit a Nature Aquarium?"}, {"a": "Not exactly. Iwagumi is a stone-focused style often considered part of the Nature Aquarium family, while Nature Aquarium also covers wood and dense planted layouts.", "q": "Is Nature Aquarium the same as Iwagumi?"}]$g$::jsonb where slug = $g$nature-aquarium$g$;
update public.glossary_terms set sections = $g$[{"text": "- Fish-only tanks: about 6 to 10 hours, mostly for viewing\n- Low-tech planted tanks: about 6 to 8 hours\n- High-tech planted tanks: about 6 to 8 hours at high intensity\n- New planted tanks: start around 6 hours and add 30 minutes every week or two if algae stays away\n\nIntensity matters as much as duration: a bright light for 6 hours can deliver more energy than a dim one for 10.", "heading": "Recommended hours"}, {"text": "A simple outlet timer or a light with a built-in schedule keeps the photoperiod identical every day, which plants and fish handle better than random hours. Many modern lights include sunrise and sunset ramps, which reduce startling fish when lights snap on.", "heading": "Use a timer"}, {"text": "Some keepers run a siesta, such as 4 hours on, 3 to 4 hours off, then 4 hours on. The idea is that algae is set back during the break while plants recover. Results are mixed, and it's debated in the hobby, but it can help if you want the tank lit in both morning and evening.", "heading": "Split photoperiods"}, {"text": "Leaving lights on 12 or more hours to enjoy the tank is one of the most common causes of algae in beginner tanks. Others include sunlight from a nearby window adding uncontrolled hours, and changing the schedule often. If algae appears, cutting the photoperiod by 1 to 2 hours is a smart first step.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$photoperiod$g$;
update public.glossary_terms set sections = $g$[{"text": "- Easy: water wisteria, Ludwigia repens, Hygrophila polysperma, Limnophila sessiliflora, Bacopa caroliniana\n- Moderate: Rotala rotundifolia, Hygrophila pinnatifida, Pogostemon stellatus 'Octopus'\n- Demanding: Rotala macrandra, Ludwigia senegalensis, Alternanthera reineckii", "heading": "Popular stem plants"}, {"text": "Remove any lead weights or rock wool from the stems. Strip the lowest one or two leaf nodes and push each stem 1 to 2 inches into the substrate with tweezers, one or two stems per hole. Spacing stems an inch or so apart gives each one light and makes a fuller group. Planting in groups of a single species looks more natural than scattering singles. Expect a little melt in the first two weeks as farm-grown stems adjust.", "heading": "How to plant them"}, {"text": "When stems reach the surface, cut the top section and replant it, which becomes a new plant. The cut stem left behind will sprout side shoots, making the group bushier. Trimming the same group in steps of different heights creates a rounded bush shape. Remove leggy, bare bottoms by replanting the tops and pulling the old stems.", "heading": "Trimming and propagation"}, {"text": "- Leggy stems with bare bases: not enough light reaching the bottom\n- Pale new leaves: iron or other nutrient shortage\n- Stunted or twisted tips: often CO2 or calcium issues\n- Melting after planting: normal for emersed-grown stems; trim back and wait\n\nIf a whole group struggles, try a brighter spot in the tank before adding more fertilizer.", "heading": "Common problems"}]$g$::jsonb where slug = $g$stem-plant$g$;
update public.glossary_terms set body = $g$Named for Diana Walstad, whose book on planted aquarium ecology popularized it, it lets plants and soil microbes handle much of the waste, which cuts down on equipment and water changes. It can be very stable once established, but it needs careful setup and patience in the first months.$g$, sections = $g$[{"text": "Soil releases nutrients and CO2 as it slowly breaks down, feeding plants without injected CO2 or much fertilizer. Plants absorb ammonia directly and compete with algae for nutrients. Floating plants handle surface nutrients and shade the tank. The result is a self-balancing system with modest fish stocking.", "heading": "How it works"}, {"text": "- Use about 1 inch of organic potting soil without added fertilizers or wetting agents; sift out wood chips\n- Cap it with 1 to 1.5 inches of fine gravel or sand\n- Plant heavily on day one with a mix of stems, floaters and rooted plants\n- Fill slowly over a plate to avoid stirring up soil\n- Use moderate light and add fish gradually after several weeks\n\nChoose a spot without direct sunlight, which can tip the balance toward algae.", "heading": "Setting one up"}, {"text": "Many Walstad tanks get water changes only every few months, mainly topping off evaporation and removing excess plant growth. Some keepers use a small filter or powerhead for circulation, which is fine. Stock lightly, since the system relies on plants to process waste.", "heading": "Maintenance"}, {"text": "Using soil with added fertilizer can cause ammonia spikes that kill fish in the first weeks. Planting too lightly invites algae. Deep vacuuming or uprooting plants releases soil into the water. Results vary by soil, water and plants, so it isn't fully hands-off, and the method's minimal water change approach is debated for heavily stocked tanks.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$walstad-method$g$;
update public.glossary_terms set body = $g$Many popular fish, including many tetras, Apistogramma, wild bettas and rasboras, evolved in blackwater habitats. Recreating it can improve their color, comfort and breeding, but the soft, low-pH conditions are less stable and need careful monitoring. It is a natural, attractive look as long as you test water regularly.$g$, sections = $g$[{"text": "In the wild, blackwater rivers like the Rio Negro have very low hardness, pH often between about 3.5 and 6, and lots of dissolved tannins and humic substances from decaying leaves. In aquariums, keepers aim for pH around 5.5 to 6.8, low KH and GH, and visibly tinted water.", "heading": "What makes water blackwater"}, {"text": "- Add driftwood, Indian almond leaves, alder cones or other aquarium-safe botanicals\n- Start with soft water, often reverse osmosis or rainwater mixed with tap\n- Use peat in the filter to soften and acidify water\n- Let leaf litter build up on the bottom as cover and grazing for fish and shrimp\n- Remove activated carbon, which strips tannins", "heading": "How to create it"}, {"text": "Cardinal tetras, rummy-nose tetras, chocolate gouramis, wild bettas, Apistogramma, discus and many rasboras do well in blackwater. Many captive-bred fish adapt to tap water but still show better color and spawning behavior in soft, tannin-rich water. Leaf litter also grows biofilm and microorganisms that fry and shrimp graze on, which helps raise young fish.", "heading": "Fish that benefit"}, {"text": "Low KH makes pH swing more easily, and a pH crash below about 5 can stall biological filtration and stress fish. Test pH and KH weekly and change water with properly prepared water. Leaves break down and add organic load, so replace them as they fall apart. Blackwater isn't suitable for livebearers, African cichlids or Neocaridina shrimp, which prefer harder water.", "heading": "Things to watch"}]$g$::jsonb where slug = $g$blackwater$g$;
update public.glossary_terms set sections = $g$[{"text": "Fish waste, decaying food and the nitrogen cycle all produce acids. Carbonate and bicarbonate absorb those acids, keeping pH stable until the buffer gets used up. Once KH runs low, pH can drop quickly, sometimes overnight. That's why stable KH matters more for most fish than hitting an exact pH number.", "heading": "How buffering works"}, {"text": "- Most community tanks: about 3 to 8 dKH (roughly 50 to 140 ppm)\n- Soft-water fish like many tetras and discus: about 1 to 4 dKH, kept stable\n- Caridina shrimp: around 0 to 2 dKH, with extra care\n- Livebearers and goldfish: about 8 to 12 dKH\n- African rift lake cichlids: 10 dKH or higher\n\nTest KH every week or two, especially in older tanks with long gaps between water changes.", "heading": "Recommended KH levels"}, {"text": "Regular water changes with tap water usually restore KH. Crushed coral or aragonite in the filter or substrate dissolves slowly to raise KH and pH. Baking soda (sodium bicarbonate) raises KH quickly; a common guide is about 1 teaspoon per 50 gallons to raise roughly 1 dKH, added slowly over a day or two. Commercial buffer products work too, but follow the label and avoid big jumps.", "heading": "Ways to add buffering"}, {"text": "Chasing pH with chemicals that lower or raise it without addressing KH leads to swings that are worse than a stable but imperfect number. Don't combine many different pH products. Raise KH gradually, by no more than 1 to 2 dKH a day, and remember that CO2 injection lowers pH temporarily without changing KH.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$buffer$g$;
update public.glossary_terms set sections = $g$[{"text": "Chloramine damages fish gills and skin, causing burns, gasping and sudden deaths, even at low concentrations. It also kills the nitrifying bacteria in your filter, which can restart the nitrogen cycle. Unlike chlorine, it stays in water for days or weeks, so it reaches your tank unless you neutralize it. A sudden fish die-off right after a water change is a classic sign that chloramine or chlorine got through.", "heading": "Why it matters"}, {"text": "- Use a water conditioner labeled to remove chloramine and treat the full volume of new water\n- Look for a conditioner that also detoxifies the ammonia left over after the chlorine is neutralized\n- Add conditioner to the bucket before fish contact the water, or to the tank before refilling with a hose\n- Carbon block filters designed for chloramine can help but aren't a substitute in most aquarium setups", "heading": "How to remove it"}, {"text": "When a conditioner breaks the chlorine-ammonia bond, the ammonia stays behind, often somewhere around 0.5 to 1 ppm in treated tap water, depending on your utility. Conditioners that bind ammonia make it temporarily less toxic, and a cycled filter then processes it. Test kits may still read ammonia after treatment, since many can't tell bound from free ammonia.", "heading": "The leftover ammonia"}, {"text": "Check your water utility's annual water quality report or call them. Many large cities in the US use chloramine, and some switch seasonally. If you're not sure, treat as though chloramine is present, since a chloramine-rated conditioner also removes chlorine.", "heading": "How to know if your water has it"}]$g$::jsonb where slug = $g$chloramine$g$;
update public.glossary_terms set sections = $g$[{"text": "Chlorine burns delicate gill tissue and skin, causing fish to gasp, dart around or die within hours. Even small amounts, around 0.2 to 0.5 ppm, can harm sensitive species. It also kills nitrifying bacteria in the filter, which can lead to ammonia and nitrite spikes after a water change.", "heading": "Why chlorine is dangerous"}, {"text": "- Use a water conditioner or dechlorinator and dose for the full volume of new water; if you refill straight from a hose, dose for the whole tank as many labels advise\n- Add it to the bucket before pouring, or to the tank before refilling with a hose\n- Aging water: plain chlorine evaporates if water sits uncovered for 24 to 48 hours with aeration, but this doesn't remove chloramine\n- Many conditioners also detoxify heavy metals, a useful bonus", "heading": "How to remove it"}, {"text": "Many utilities use chloramine instead, or switch between the two. Chloramine doesn't evaporate and releases ammonia when treated. A conditioner that handles chloramine works for both, so it's the safe default if you're unsure what your city uses.", "heading": "Chlorine vs chloramine"}, {"text": "Forgetting to dose when topping off evaporation or using a hose direct from the tap is a frequent slip. Others include dosing for only the replaced water when filling from a hose directly into the tank, and rinsing filter media in tap water, which kills bacteria. Rinse media in old tank water instead. Well water usually has no chlorine but should still be tested for other issues.", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$chlorine$g$;
update public.glossary_terms set sections = $g$[{"text": "Low-tech tanks with low to moderate light and plants like anubias, java fern, cryptocorynes and mosses do fine on the CO2 that fish and bacteria produce. Added CO2 makes the biggest difference in tanks with strong lighting and demanding stem plants or carpeting plants, where CO2 is usually what runs out first.\n\nIf you raise the light without raising CO2, plants can't keep up, and algae takes the leftover light and nutrients. That mismatch is the most common reason high-light tanks turn into algae farms.", "heading": "Do you need added CO2?"}, {"text": "- Pressurized systems: a cylinder, regulator, solenoid, bubble counter and diffuser or reactor. This is the most stable and controllable option, and the usual choice for tanks over 20 gallons.\n- DIY yeast or citric acid reactors: cheap and fine for small tanks, but output varies and can surge.\n- Liquid carbon products: usually a glutaraldehyde-based supplement that gives a modest boost. Some plants, like vallisneria and some mosses, melt from it, and it should be dosed carefully around shrimp.", "heading": "How CO2 is added"}, {"text": "Most planted tanks aim for roughly 20 to 30 ppm. A drop checker filled with 4 dKH reference solution turns green in that range, blue when CO2 is low and yellow when it is too high. Because drop checkers lag by one to two hours, watch your fish as you raise the rate.\n\nRun CO2 on a timer so it starts one to two hours before the lights and shuts off about an hour before they go off. Keep gentle surface ripple so oxygen can still get in. If fish gasp at the surface, turn CO2 off, add an airstone and do a water change.", "heading": "Dialing it in safely"}, {"text": "- Raising the bubble rate quickly instead of in small steps over several days.\n- Running CO2 all night, when plants aren't using it.\n- Measuring CO2 with the pH and KH chart when the water has tannins or buffers, which gives misleading numbers.\n- Ignoring a nearly empty cylinder, which can dump gas suddenly on some regulators.", "heading": "Common mistakes"}]$g$::jsonb, faq = $g$[{"a": "At the 20 to 30 ppm most planted tanks target, healthy fish are fine. Problems start when levels climb much higher, which causes gasping, lethargy and can kill fish quickly.", "q": "Is CO2 bad for fish?"}, {"a": "Yes. Plants don't photosynthesize in the dark, so CO2 at night only builds up while fish and plants use oxygen, which can leave fish gasping by morning. A solenoid on a timer handles this automatically.", "q": "Should I turn off CO2 at night?"}, {"a": "Absolutely. Low-tech tanks with modest light and hardy plants grow slower but stay healthy and need far less fine-tuning.", "q": "Can I have a planted tank without CO2?"}]$g$::jsonb where slug = $g$co2$g$;
update public.glossary_terms set sections = $g$[{"text": "Many cities have switched from chlorine to chloramine, which is chlorine bound to ammonia. Chlorine alone will gas off if water sits out for a day or two, but chloramine will not, so the old trick of letting water stand no longer works for most tap water.\n\nWhen a conditioner breaks chloramine apart, it releases a small amount of ammonia. A cycled filter handles that easily, and many conditioners also bind ammonia temporarily so it's less harmful. Check your water utility's annual report to see which disinfectant it uses.", "heading": "Chlorine vs chloramine"}, {"text": "- Dose for the volume of new water you're adding, not the whole tank, unless the label says otherwise.\n- Add it to the bucket before pouring. If you refill straight from a hose, many labels say to dose for the whole tank volume.\n- Slight overdosing is generally safe with common conditioners, and many keepers add a little extra when chloramine levels are high.\n- Use it for every top-off and water change that uses tap water. Rinse filter media in old tank water rather than tap water.", "heading": "How to dose it"}, {"text": "Some formulas also detoxify heavy metals like copper and zinc from old plumbing, add a slime coat aid, or temporarily bind ammonia, nitrite and nitrate. The binding is temporary, roughly a day or two, and it does not remove those compounds or replace water changes. Test kits for ammonia may still show a reading after dosing, since salicylate tests detect bound ammonia too.", "heading": "What else conditioners do"}, {"text": "RO water, distilled water and rainwater collected cleanly contain no chlorine, so they don't need conditioner. Well water usually isn't chlorinated either, but it's worth testing for metals, nitrate and hardness before using it.", "heading": "When you don't need it"}]$g$::jsonb where slug = $g$dechlorinator$g$;
update public.glossary_terms set sections = $g$[{"text": "- Fish gasping or crowding at the surface, especially near the filter outflow\n- Rapid gill movement and lethargy\n- Shrimp and snails climbing to the waterline\n- Losses that happen overnight or early in the morning, when plants have been using oxygen all night", "heading": "Signs of low oxygen"}, {"text": "Temperature matters most: water at 86°F holds noticeably less oxygen than water at 72°F, while fish need more of it as they warm up. Overstocking, uneaten food and decay, heavy medication, and injected CO2 also cut oxygen.\n\nPlants add oxygen during the day but use it at night, so a densely planted tank with little surface movement can run low before dawn. A film of oil or protein on the surface also blocks gas exchange.", "heading": "What lowers oxygen"}, {"text": "Oxygen enters water at the surface, so surface movement is what counts. Point the filter outflow or a powerhead so the surface ripples, add an airstone, or lower the water level slightly so a hang-on-back filter splashes. Bubbles help mostly by moving water, not by the bubbles themselves.\n\nIn an emergency, do a 25 to 50 percent water change with temperature-matched, dechlorinated water and add aeration immediately. Healthy tanks generally sit around 6 to 8 mg/L; below about 5 mg/L, many fish start to struggle.", "heading": "How to raise it"}, {"text": "Stock sensibly, avoid overfeeding, keep filters clean and flowing, and add an airstone during heat waves or when treating with medication. Battery air pumps are worth keeping for power outages.", "heading": "Prevention"}]$g$::jsonb where slug = $g$dissolved-oxygen$g$;
update public.glossary_terms set sections = $g$[{"text": "One dGH equals about 17.9 ppm. Rough ranges:\n\n- 0 to 4 dGH: very soft\n- 4 to 8 dGH: soft\n- 8 to 12 dGH: moderately hard\n- 12 to 18 dGH: hard\n- Over 18 dGH: very hard\n\nGH is not the same as KH. KH measures carbonates that buffer pH, while GH measures calcium and magnesium. They often rise together in tap water but can be very different, especially in remineralized RO water.", "heading": "Reading the numbers"}, {"text": "Soft-water fish like many tetras, rasboras, discus and wild bettas do best around 2 to 8 dGH, especially for breeding. Livebearers, African rift lake cichlids and many rainbowfish prefer 10 to 20 dGH or more. Neocaridina shrimp like roughly 6 to 10 dGH, Caridina shrimp prefer about 4 to 6, and snails need moderate GH to grow strong shells.\n\nMany captive-bred fish adapt to a wider range than their wild relatives, so stability usually matters more than hitting an exact number.", "heading": "What different species need"}, {"text": "- To raise: use a GH remineralizer, crushed coral or aragonite, or wonder shell style mineral blocks in small amounts.\n- To lower: mix tap water with RO, distilled or rainwater. Peat can soften water slightly and driftwood lowers pH a little, but neither is a strong or predictable way to lower GH.\n- Change GH slowly, no more than a couple of degrees per day, especially with shrimp.", "heading": "How to raise or lower GH"}, {"text": "Liquid drop kits for GH count drops until the color changes, with each drop usually equal to one degree. Test your tap water as well as your tank, since evaporation and top-offs with tap water slowly raise GH over time.", "heading": "Testing tips"}]$g$::jsonb where slug = $g$gh$g$;
update public.glossary_terms set sections = $g$[{"text": "KH, or carbonate hardness, measures the carbonates and bicarbonates dissolved in water. Its job in a tank is buffering: it soaks up acids and keeps pH from swinging. It's measured in degrees (dKH) or parts per million, where 1 dKH equals about 17.9 ppm.", "heading": "KH, explained"}, {"text": "Fish, bacteria and decaying waste all produce acid. With enough KH, pH stays steady. With too little, the buffer runs out and pH can crash overnight, which stresses fish and stalls beneficial bacteria. Low KH is common in soft tap water, RO water and tanks with lots of driftwood or active soil.", "heading": "Why it matters"}, {"text": "- Most community freshwater tanks: about 3 to 8 dKH\n- Soft-water fish like tetras and discus: lower, often 1 to 4 dKH, kept stable\n- Livebearers: higher, around 8 to 12 dKH\n- African rift lake cichlids: 10 dKH or higher\n- Reef tanks: about 7 to 11 dKH", "heading": "Good KH ranges"}, {"text": "To raise KH, add crushed coral or aragonite to the filter or substrate, or dose small amounts of baking soda (sodium bicarbonate) dissolved in water, changing it slowly. To lower it, mix in RO or distilled water at water changes. Test before and after every change.", "heading": "Raising or lowering KH"}]$g$::jsonb where slug = $g$kh$g$;
update public.glossary_terms set faq = $g$[{"a": "Long-term exposure above about 40 to 80 ppm harms most fish, and sudden very high levels over 100 ppm can be dangerous. Sensitive species need it lower.", "q": "What level of nitrate is toxic to fish?"}, {"a": "In most tanks you don't need to. Keeping it under 20 ppm with water changes and plants is the realistic, healthy target.", "q": "How do I get nitrate to zero?"}, {"a": "No. Some conditioners claim to detoxify nitrate for a short time, but none remove it. Only water changes, plants or special media actually remove it.", "q": "Does a water conditioner remove nitrate?"}]$g$::jsonb where slug = $g$nitrate$g$;
update public.glossary_terms set faq = $g$[{"a": "During a fishless cycle it often lasts one to three weeks, and sometimes longer. In an established tank with a minor disruption, it usually clears within a few days with water changes.", "q": "How long does a nitrite spike last?"}, {"a": "Zero. Anything above about 0.25 ppm stresses fish, and readings of 1 ppm or more are an emergency.", "q": "What is a safe nitrite level for fish?"}, {"a": "Your ammonia-eating bacteria are working, but the nitrite-eating bacteria haven't caught up yet. It's common during cycling and resolves with time and water changes.", "q": "Why do I have nitrite but no ammonia?"}]$g$::jsonb where slug = $g$nitrite$g$;
update public.glossary_terms set definition = $g$A 0 to 14 scale measuring how acidic or alkaline your water is.$g$, body = $g$Most common freshwater fish thrive between roughly 6.5 and 7.8, but stability matters far more than hitting an exact number. Sudden pH swings are more harmful than a steady value slightly outside a species' ideal range.$g$ where slug = $g$ph$g$;
update public.glossary_terms set sections = $g$[{"text": "The nitrogen cycle and decaying organics constantly produce acid. Carbonates, measured as KH, neutralize that acid and hold pH steady. When KH is low to begin with, or water changes are skipped, the buffer runs out and pH falls fast.\n\nTanks with soft tap water, lots of driftwood or peat, heavy stocking, or CO2 injection with very low KH are most at risk. Once pH drops below about 6, nitrifying bacteria slow down sharply, which can cause ammonia to build up later.", "heading": "Why it happens"}, {"text": "- KH test reading 1 to 2 dKH or lower\n- pH noticeably lower than a week ago\n- Fish suddenly lethargic, hiding, gasping or with clamped fins\n- Cloudy water or rising ammonia after a stretch of low pH", "heading": "Warning signs"}, {"text": "Do a 20 to 30 percent water change with dechlorinated tap water, assuming your tap water has reasonable KH. Repeat over a few days rather than all at once so pH rises gradually. Raise KH long term with a small bag of crushed coral or aragonite in the filter, or a measured dose of baking soda: about 1 teaspoon per 50 gallons raises KH by roughly 1 dKH. Add baking soda slowly and retest before adding more. If ammonia has built up during the low pH, lower it with water changes first, because ammonia becomes more toxic as pH rises.\n\nAvoid pH-down or pH-up chemicals without fixing KH; they cause swings, not stability.", "heading": "How to fix it"}, {"text": "Keep KH at 3 dKH or higher for most community tanks, test KH every week or two, keep up with water changes, and don't overstock.", "heading": "Prevention"}]$g$::jsonb where slug = $g$ph-crash$g$;
update public.glossary_terms set definition = $g$Remineralization is the process of adding measured minerals back into RO, distilled or rainwater so it reaches the target GH, KH and TDS a species needs.$g$, sections = $g$[{"text": "RO and distilled water have GH and KH near zero. Fish and invertebrates need calcium and magnesium for normal body function, and shrimp need them to molt properly. With no KH, pH can also swing wildly. Using pure RO water straight in a tank is a common and avoidable mistake.", "heading": "Why pure water needs minerals"}, {"text": "- Collect RO or distilled water in a clean container.\n- Add a remineralizer product formulated for your target: GH-only for Caridina shrimp kept on buffering soil, or GH plus KH for Neocaridina, soft-water fish and general community tanks.\n- Stir until fully dissolved, then test GH, KH and TDS.\n- Adjust gradually, and write down how much you used per gallon so you can repeat it exactly.\n- Match temperature, then use it for water changes and top-offs.", "heading": "How to do it"}, {"text": "- Caridina shrimp, such as crystal reds: GH 4 to 6, KH 0 to 1, TDS about 100 to 160\n- Neocaridina shrimp, such as cherry shrimp: GH 6 to 10, KH 2 to 6, TDS about 150 to 250\n- Soft-water fish like discus or wild bettas: GH 2 to 6, KH 1 to 4\n\nThese are typical hobby ranges; breeders vary.", "heading": "Common targets"}, {"text": "Evaporation removes water, not minerals. Top off with plain RO water to replace evaporation, and use remineralized water for water changes, otherwise TDS creeps up. Don't use RO water straight for changes, and avoid making large jumps in GH or TDS, which can cause failed molts in shrimp.", "heading": "Top-offs and mistakes"}]$g$::jsonb where slug = $g$remineralization$g$;
update public.glossary_terms set definition = $g$RO water is tap water passed through carbon prefilters and a reverse osmosis membrane, which together strip out nearly all minerals, chlorine, metals, nitrate and other dissolved contaminants.$g$, sections = $g$[{"text": "- Your tap water is very hard and you keep soft-water species\n- Tap water has high nitrate, phosphate, silicate or metals that cause problems\n- You keep Caridina shrimp, discus or other sensitive fish\n- You want consistent water that doesn't change with the seasons\n\nMost community fish do fine in dechlorinated tap water, so RO isn't necessary for every tank.", "heading": "When RO is worth it"}, {"text": "A home RO unit pushes tap water through sediment and carbon prefilters, then the membrane. RO/DI units add a deionization stage for near-zero TDS. Expect waste water: many units send 2 to 4 gallons down the drain for every gallon made, though that water can go to plants or the garden. Replace prefilters every 6 to 12 months and check output with a TDS meter; rising TDS means the membrane is wearing out.", "heading": "How a unit works"}, {"text": "Never use straight RO for water changes. Either remineralize it to target GH and KH or blend it with tap water. For example, a 50/50 mix of RO and tap water roughly halves your tap's hardness. RO from a unit with fresh carbon prefilters usually doesn't need dechlorinator, but blends with tap water do. Use plain RO only for topping off evaporation.", "heading": "Using RO safely"}, {"text": "You can buy a home unit, or buy RO water from fish stores and grocery store refill machines. Store-bought water is fine, but check its TDS, since poorly maintained machines can drift.", "heading": "Where to get it"}]$g$::jsonb, faq = $g$[{"a": "Yes, once remineralized or blended. Pure RO lacks the minerals fish need and can let pH swing.", "q": "Is RO water good for fish?"}, {"a": "They are close. Both are nearly mineral-free and are used the same way in aquariums, as long as you remineralize.", "q": "Is distilled water the same as RO water?"}, {"a": "Usually not. The carbon prefilters remove chlorine, but chloramine needs carbon rated for it and changed on schedule, so check this if your water supplier uses chloramine. If you blend in tap water, dose conditioner for the tap portion.", "q": "Do I need dechlorinator with RO water?"}]$g$::jsonb where slug = $g$ro-water$g$;
update public.glossary_terms set sections = $g$[{"text": "- Freshwater: under about 0.5 ppt, specific gravity about 1.000\n- Low brackish: about 2 to 10 ppt, specific gravity about 1.002 to 1.007\n- High brackish: about 10 to 25 ppt, up to roughly 1.018\n- Marine and reef: about 35 ppt, specific gravity about 1.024 to 1.026\n\nBrackish fish include bumblebee gobies, figure eight puffers, archerfish and some mollies, though many of these are sold in freshwater stores. Research each species carefully.", "heading": "The main ranges"}, {"text": "Use a refractometer calibrated with a 35 ppt calibration fluid; it's the most accurate common tool. Swing-arm hydrometers are cheaper but less precise and need bubble-free readings. Temperature affects readings, so measure at tank temperature or use a temperature-compensated tool.\n\nCheck salinity weekly at first, and always after topping off or doing a water change, so you learn how quickly your tank drifts.", "heading": "How to measure it"}, {"text": "Always mix marine salt or brackish water in a separate container, never directly in the tank. Change salinity slowly, no more than about 0.001 to 0.002 specific gravity per week, for example with each water change. Remember that evaporation raises salinity: top off with fresh, dechlorinated water, not saltwater. Use marine salt mix, not table salt or aquarium salt, for brackish and marine setups.", "heading": "Changing salinity safely"}, {"text": "Aquarium salt is sometimes used short-term to treat ich or nitrite poisoning, but it doesn't belong permanently in most freshwater tanks. Corydoras, loaches, many tetras, shrimp, snails and lots of plants are sensitive to it.", "heading": "Salt in freshwater tanks"}]$g$::jsonb where slug = $g$salinity$g$;
update public.glossary_terms set definition = $g$Tannins are natural plant compounds released by driftwood, leaves, cones and peat that tint aquarium water tea-colored and can slightly acidify it, especially in soft water.$g$, sections = $g$[{"text": "- New driftwood, especially mopani, Malaysian and spiderwood\n- Indian almond leaves, oak and guava leaves\n- Alder cones, seed pods and other botanicals\n- Peat moss and some aquasoils\n\nNew wood can leach heavily for weeks or even months, then slowly taper off.\n\nTannin release is strongest in the first weeks after you add new material and in soft water, where the color shows faster.", "heading": "Where they come from"}, {"text": "Tannins and the humic substances that come with them lower pH slightly, mostly in soft water with little KH. Many keepers believe they have mild antibacterial and antifungal effects, though the evidence is mostly anecdotal. Fish from blackwater habitats, such as bettas, apistogrammas, many tetras, rasboras and gouramis, often show better color and feel more secure in stained water.\n\nThe color itself does not harm fish or plants, though very dark water reduces the light reaching plants.", "heading": "Benefits and effects"}, {"text": "- Boil or soak new driftwood before use, changing the water every few days\n- Run activated carbon or a synthetic adsorbent resin in the filter\n- Keep up with regular water changes\n- Remove leaves and botanicals once they break down\n\nIf you want blackwater, simply keep adding leaves or botanicals and skip the carbon.", "heading": "How to reduce tannins"}, {"text": "In tanks with very low KH, heavy tannin use can drop pH more than expected, so test pH and KH when you add lots of botanicals. Livebearers and African cichlids prefer harder, alkaline water and may not do as well in strong blackwater.", "heading": "When to be careful"}]$g$::jsonb where slug = $g$tannins$g$;
update public.glossary_terms set sections = $g$[{"text": "Brackish water is water that is saltier than fresh water but less salty than the ocean. In nature it forms where rivers meet the sea: estuaries, mangroves and tidal marshes. The salt level swings with the tide and the rain, so fish that live there handle change well.", "heading": "Brackish water, explained"}, {"text": "Aquarists measure salt as specific gravity (SG). Fresh water is 1.000 and the ocean is about 1.025. Brackish tanks usually run somewhere between 1.002 and 1.015, and up to about 1.018 for some species. Low-end brackish (1.002 to 1.005) suits fish like mollies and bumblebee gobies; figure-8 puffers are usually kept around 1.005 to 1.008; high-end brackish (1.010 and up) suits monos and scats as they mature.", "heading": "How salty is brackish?"}, {"text": "- Figure-8 puffers\n- Bumblebee gobies\n- Mollies (they also live fine in fresh water)\n- Archerfish\n- Monos and scats (they grow large and head toward full saltwater as adults)\n- Knight gobies and some glassfish", "heading": "Popular brackish fish"}, {"text": "Use marine salt mix made for reef tanks, not aquarium salt or table salt; marine mix adds the minerals fish need. Measure with a refractometer or hydrometer, and change salinity slowly, no more than about 0.002 SG per week. Most freshwater plants won't handle the salt, but Java fern, anubias and some cryptocorynes tolerate low-end brackish.", "heading": "Setting up a brackish tank"}]$g$::jsonb, faq = $g$[{"a": "No. A little aquarium salt in a freshwater tank is a treatment, not a brackish setup. Brackish tanks use marine salt mix at a measured specific gravity.", "q": "Is aquarium salt the same as brackish water?"}, {"a": "Only a few, such as mollies and some livebearers. Most tropical freshwater fish are stressed or killed by sustained salt.", "q": "Can freshwater fish live in brackish water?"}, {"a": "Roughly 1.002 to 1.015 for most brackish tanks, up to about 1.018 for some species. Full saltwater is about 1.025.", "q": "What specific gravity is brackish?"}]$g$::jsonb where slug = $g$brackish$g$;
update public.glossary_terms set sections = $g$[{"text": "Match three things: temperament, size and water needs. Avoid fish big enough to swallow tankmates, and avoid pairing fin nippers like tiger barbs with long-finned fish like bettas or angelfish. Then check that temperature, pH and hardness ranges overlap.\n\nThink in layers: a schooling group in the middle, bottom dwellers like corydoras, and maybe one centerpiece fish.", "heading": "Choosing compatible fish"}, {"text": "- 20 gallons: a school of 8 to 10 small tetras or rasboras, 6 corydoras and a few nerite snails\n- 29 gallons: harlequin rasboras, platies, a group of kuhli loaches and a honey gourami\n- 40 gallons or more: a larger tetra school, a single dwarf gourami or a pearl gourami, and a group of corydoras\n\nSchooling fish should be kept in groups of 6 or more.", "heading": "Beginner-friendly combinations"}, {"text": "Cycle the tank first. Add fish in small groups over weeks, starting with the hardiest, so the bacteria keep up. Quarantine new fish for 2 to 4 weeks if you can, since one sick newcomer can infect the whole tank.\n\nWatch new arrivals closely for the first few days for chasing, hiding or torn fins, and be ready to rehome a fish that doesn't fit in. Plenty of plants and decor help break lines of sight and reduce squabbles.", "heading": "Adding fish the right way"}, {"text": "- Buying fish on impulse without checking adult size\n- Keeping schooling fish in groups of two or three\n- Overstocking, which raises waste and aggression\n- Adding a single aggressive fish to a peaceful group", "heading": "Common mistakes"}]$g$::jsonb where slug = $g$community-tank$g$;
update public.glossary_terms set sections = $g$[{"text": "- Salinity: about 1.025 to 1.026 specific gravity, around 35 ppt\n- Temperature: about 76 to 79 F\n- Alkalinity: about 7 to 11 dKH\n- Calcium: about 400 to 450 ppm\n- Magnesium: about 1,250 to 1,400 ppm\n- Nitrate and phosphate: low but not zero for most corals\n\nStability matters more than chasing exact numbers. Corals react badly to quick swings, especially in alkalinity.", "heading": "Key parameters"}, {"text": "Most reefs use live rock, a reef-capable light, powerheads for strong varied flow, a heater, a protein skimmer on larger tanks, an RO/DI unit for clean water, a refractometer and reliable test kits. Many keepers add a sump and an automatic top-off to keep salinity stable.", "heading": "Essential equipment"}, {"text": "Soft corals like leathers, zoanthids, mushrooms and many polyps are the easiest starting point. LPS corals like hammers and torches need more stable chemistry. SPS corals like acropora are the most demanding and need very stable alkalinity and strong light. Start with soft corals and build experience.\n\nBuy frags, small cuttings of coral, rather than large colonies at first. They're cheaper, adapt better and let you learn how your tank's light and flow affect growth.", "heading": "Choosing corals"}, {"text": "Let the tank mature for a few months before adding demanding corals. Add fish slowly, quarantine them, and research reef-safety, since some fish and invertebrates eat corals. Never use copper medications in a reef tank, since copper is deadly to corals and invertebrates.", "heading": "Tips for success"}]$g$::jsonb where slug = $g$reef-tank$g$;
update public.glossary_terms set faq = $g$[{"a": "Yes, somewhat. It needs more equipment and testing, but many hobbyists keep successful fish-only tanks as beginners.", "q": "Is saltwater harder than freshwater?"}, {"a": "Most can't. Nearly all freshwater fish die in marine salinity and most marine fish die in freshwater. A few hardy exceptions, such as mollies, can be acclimated very slowly to higher salinity.", "q": "Can freshwater fish live in saltwater?"}, {"a": "Captive-bred clownfish are among the hardiest and most popular starter marine fish.", "q": "What is the easiest saltwater fish?"}]$g$::jsonb where slug = $g$saltwater$g$;

