-- Quiz questions
do $q$
declare opts_type text;
begin
  select udt_name into opts_type from information_schema.columns
  where table_schema = 'public' and table_name = 'course_questions' and column_name = 'options';
  if opts_type in ('jsonb', 'json') then
    update public.course_questions set options = $j$["A bigger meal of flakes", "A small piece of cooked, shelled pea", "Turning off the filter"]$j$::jsonb where prompt = $p$What can help many plant-eating fish with constipation after a short fast?$p$;
  else
    update public.course_questions set options = array(select jsonb_array_elements_text($j$["A bigger meal of flakes", "A small piece of cooked, shelled pea", "Turning off the filter"]$j$::jsonb)) where prompt = $p$What can help many plant-eating fish with constipation after a short fast?$p$;
  end if;
  if opts_type in ('jsonb', 'json') then
    update public.course_questions set options = $j$["Oscar", "Redtail catfish", "Otocinclus"]$j$::jsonb where prompt = $p$Which small catfish eats brown diatoms?$p$;
  else
    update public.course_questions set options = array(select jsonb_array_elements_text($j$["Oscar", "Redtail catfish", "Otocinclus"]$j$::jsonb)) where prompt = $p$Which small catfish eats brown diatoms?$p$;
  end if;
  update public.course_questions set prompt = $p$Which temperature ranges are right for goldfish and for tropical fish?$p$ where prompt = $p$Which temperature ranges are right?$p$;
  update public.course_questions set prompt = $p$Which of these do most fish handle worst?$p$ where prompt = $p$What do most fish handle worse?$p$;
  if opts_type in ('jsonb', 'json') then
    update public.course_questions set options = $j$["Advanced ich, where the white spots have grown together", "Normal slime coat that's thicker than usual", "Algae that has started growing on the fish", "Columnaris, a bacterial infection that looks like fungus"]$j$::jsonb where prompt = $p$A fish has white cottony tufts that don't improve after a few days of antifungal medicine. What could it be?$p$;
  else
    update public.course_questions set options = array(select jsonb_array_elements_text($j$["Advanced ich, where the white spots have grown together", "Normal slime coat that's thicker than usual", "Algae that has started growing on the fish", "Columnaris, a bacterial infection that looks like fungus"]$j$::jsonb)) where prompt = $p$A fish has white cottony tufts that don't improve after a few days of antifungal medicine. What could it be?$p$;
  end if;
  update public.course_questions set correct_index = 3 where prompt = $p$A fish has white cottony tufts that don't improve after a few days of antifungal medicine. What could it be?$p$;
  update public.course_questions set explanation = replace(explanation, $e$Driftwood and peat release tannins that soften water and lower pH.$e$, $e$Driftwood and peat release tannins that can lower pH a little, and peat can also soften water. Neither adds hardness.$e$) where prompt = $p$What can you add to a filter to raise KH and GH slowly?$p$;
end $q$;

